function notificationTone(message, tone = '') {
  const requested=String(tone || '').toLowerCase();
  if (['error','warning','success','info'].includes(requested)) return requested;
  return /لا تملك الصلاحية|غير مصرح|سالب|غير صالح|تعذر|خطأ|يجب|لا يمكن/.test(String(message)) ? 'error' : 'success';
}
function showToast(message, tone = '') {
  const state=notificationTone(message,tone);
  const meta={success:{label:'تمت العملية',icon:'✓'},warning:{label:'تنبيه',icon:'!'},error:{label:'تعذر الإجراء',icon:'×'},info:{label:'معلومة',icon:'i'}}[state];
  toast.innerHTML=`<span class="toast-icon" aria-hidden="true">${meta.icon}</span><span class="toast-copy"><strong>${meta.label}</strong><span>${escapeHtml(message)}</span></span>`;
  toast.classList.remove('toast-error','toast-warning','toast-success','toast-info');
  toast.classList.add(`toast-${state}`);
  toast.classList.add('show');
  setTimeout(() => toast.classList.remove('show'), 2600);
}
function presentOperationError(message) {
  const text=String(message || 'تعذر إتمام العملية');
  const active=document.activeElement;
  if (active?.matches?.('input[type="number"]')) { active.classList.add('field-invalid'); active.setAttribute('aria-invalid','true'); active.focus(); }
  if (/سالب|أكبر من صفر|غير صالح/.test(text)) return showToast(`تحقق من المبلغ: ${text}`,'error');
  if (/لا تملك الصلاحية|غير مصرح|مدير النظام/.test(text)) return showToast(`إجراء غير مصرح: ${text}`,'error');
  showToast(text,'error');
}
