function todayIso() { const control=settings?.systemDateControl||{}; const manual=String(control.manualDate||''); return control.mode==='manual'&&/^\d{4}-\d{2}-\d{2}$/.test(manual)&&!Number.isNaN(new Date(`${manual}T00:00:00`).getTime())?manual:localIsoDate(); }
