function operationDateTime(value) { if (!value) return '—'; if (value instanceof Date) return `${formatArabicDate(localIsoDate(value))} — ${String(value.getHours()).padStart(2, '0')}:${String(value.getMinutes()).padStart(2, '0')}`; const raw = String(value); const date = operationIsoDate(raw); const time = raw.match(/[T\s](\d{2}:\d{2})/)?.[1] || ''; return `${formatArabicDate(date)}${time ? ` — ${time}` : ''}`; }
function parseArabicDate(value) { const clean = String(value || '').trim().replace(/[.\-]/g, '/'); const match = clean.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/); if (!match) return ''; const day = String(match[1]).padStart(2, '0'); const month = String(match[2]).padStart(2, '0'); const year = match[3]; const iso = `${year}-${month}-${day}`; return Number.isNaN(new Date(`${iso}T00:00:00`).getTime()) ? '' : iso; }
