function syncArabicDateInput(id, value, normalize = false) { const iso = parseArabicDate(value); const picker = document.getElementById(id); const display = document.getElementById(`${id}Display`); if (iso && picker) picker.value = iso; if (normalize && display && iso) display.value = formatArabicDate(iso); if (normalize && !iso && display?.value) showToast('اكتب التاريخ بصيغة يوم/شهر/سنة'); }
