function enhanceDateInputs() { view.querySelectorAll('input[type="date"]:not(.native-date-picker)').forEach((input) => { if (input.dataset.arabicEnhanced || !input.id) return; input.dataset.arabicEnhanced = '1'; const id = input.id; const wrapper = document.createElement('div'); wrapper.className = 'arabic-date-field'; const display = document.createElement('input'); display.id = `${id}Display`; display.className = 'arabic-date-text'; display.placeholder = 'يوم/شهر/سنة'; display.inputMode = 'numeric'; display.value = formatArabicDate(input.value); display.addEventListener('input', () => { const iso = parseArabicDate(display.value); if (iso) input.value = iso; }); display.addEventListener('blur', () => { const iso = parseArabicDate(display.value); if (iso) { input.value = iso; display.value = formatArabicDate(iso); } else if (display.value) showToast('اكتب التاريخ بصيغة يوم/شهر/سنة'); }); const button = document.createElement('button'); button.type = 'button'; button.className = 'date-picker-trigger'; button.title = 'اختيار التاريخ'; button.textContent = '▣'; button.addEventListener('click', () => { if (input.showPicker) input.showPicker(); else input.click(); }); input.classList.add('native-date-picker'); input.addEventListener('input', () => { display.value = formatArabicDate(input.value); }); input.parentNode.insertBefore(wrapper, input); wrapper.append(display, button, input); }); }
