function needsCoreDirectoryRecovery() { const diagnostics=Array.isArray(live.loadDiagnostics) ? live.loadDiagnostics : []; const failedCoreSection=diagnostics.some((item) => coreDirectoryKeys.includes(item?.key)); return failedCoreSection || !Array.isArray(live.currencies) || !Array.isArray(live.accounts) || !Array.isArray(live.cashboxes); }
