async function refreshLiveData(silent = false) {
  const response = await window.sarafa.dataCall('bootstrap');
  if (!response.ok) { if (!silent) showToast(response.error); return false; }
  live = response.data;
  live.loadDiagnostics=Array.isArray(live.loadDiagnostics) ? live.loadDiagnostics : [];
  normalizeOperationLogDates();
  liveDataReady = true;
  coreDirectoriesReady = !needsCoreDirectoryRecovery();
  return true;
}
function ensureLiveData() {
  if (liveDataReady) return Promise.resolve(true);
  if (!liveDataTask) liveDataTask = refreshLiveData(true).finally(() => { liveDataTask = null; });
  return liveDataTask;
}
function isCoreDirectoryView(name) { return name === 'accounts' || name === 'cashboxes' || name === 'cashbox-inventory'; }
function requiresCoreDirectories(name) { return coreDirectoryViewNames.has(name); }
function requiresCustomerDirectories(name) { return customerDirectoryViewNames.has(name); }
