function updateAppUpdateCard({ message, tone='neutral', currentVersion, downloadReady=false } = {}) { const card=document.getElementById('appUpdateCard'); const status=document.getElementById('appUpdateStatus'); const current=document.getElementById('appUpdateCurrent'); const download=document.getElementById('appUpdateDownloadButton'); const install=document.getElementById('appUpdateInstallButton'); const reveal=document.getElementById('appUpdateOpenButton'); if (!card || !status) return; card.dataset.updateTone=tone; status.textContent=message || 'جاهز لفحص التحديث'; if (currentVersion) current.textContent=`الإصدار الحالي ${currentVersion}`; if (download) download.hidden=!downloadReady; if (install) install.hidden=!downloadedAppUpdatePath; if (reveal) reveal.hidden=!downloadedAppUpdatePath; }
