async function checkAppUpdate() { updateAppUpdateCard({ message:'جارٍ فحص الإصدار المتاح…', tone:'checking' }); const result=await window.sarafa.checkAppUpdate?.(); if (!result?.ok) { updateAppUpdateCard({ message:result?.error || 'تعذر فحص التحديث', tone:'error' }); return; } if (result.reason === 'not-configured') { updateAppUpdateCard({ currentVersion:result.currentVersion, message:'لم يُضبط مصدر التحديث بعد. أضفه من إعدادات النظام.', tone:'notice' }); return; } if (!result.available) { updateAppUpdateCard({ currentVersion:result.currentVersion, message:result.reason === 'installed-newer' ? 'الإصدار المثبت أحدث من المصدر المعتمد.' : 'أنت تستخدم أحدث إصدار متاح.', tone:'success' }); return; } updateAppUpdateCard({ currentVersion:result.currentVersion, message:`يتوفر الإصدار ${result.manifest.version}. راجع الملاحظات ثم اختر تنزيلًا آمنًا.`, tone:'available', downloadReady:true }); }
async function downloadLatestAppUpdate() { updateAppUpdateCard({ message:'جارٍ تنزيل التحديث والتحقق من بصمة SHA-256…', tone:'checking' }); const result=await window.sarafa.downloadAppUpdate?.(); if (!result?.ok) { updateAppUpdateCard({ message:result?.error || 'تعذر تنزيل التحديث', tone:'error' }); return; } downloadedAppUpdatePath=result.downloaded.path; downloadedAppUpdateVersion=result.version; updateAppUpdateCard({ currentVersion:result.currentVersion, message:`تم التحقق من الإصدار ${result.version}. اختر «نسخ ثم إعادة تشغيل» لإنشاء نسخة احتياطية لحظية وتثبيت التحديث.`, tone:'success' }); showToast('تم تنزيل التحديث والتحقق من بصمته بنجاح'); }
