async function refreshLoginConnectionStatus() { setLoginDatabaseState('checking','جارٍ فحص اتصال MySQL…','يظهر وضع الاتصال هنا قبل تسجيل الدخول.'); try { const result=await window.sarafa.dbStatus(); if (result?.connected) setLoginDatabaseState('success','اتصال MySQL جاهز','قاعدة البيانات المحلية جاهزة للعمل.'); else setLoginDatabaseState('error','MySQL غير متصل','تحقق من تشغيل الخدمة وبيانات الاتصال المحمية.'); } catch { setLoginDatabaseState('error','MySQL غير متصل','تعذر فحص الخدمة أو بيانات الاتصال المحمية.'); } }
