function showLogin(error = '') { document.body.classList.remove('module-loading'); document.getElementById('loginError').textContent = error; document.getElementById('loginOverlay').classList.remove('login-hidden'); document.getElementById('loginPassword').focus(); loadLoginAppInfo(); refreshLoginConnectionStatus(); }
async function completeStartup(session) {
  try {
    applySession(session);
    await loadHeaderAppInfo();
    document.getElementById('loginOverlay').classList.add('login-hidden');
    settings = { ...settings, ...(await window.sarafa.getSettings()) };
    applyAppearance();
    applyOptionalModules();
    applyPerformanceTools();
    applyPrintOptions();
    await refreshTopConnectionStatus();
    window.applyUiDesigner?.();
    window.applyDesignStudio?.();
    document.getElementById('branchName').textContent = settings.branch;
    document.getElementById('currencyName').textContent = settings.baseCurrency;
    document.getElementById('fiscalYear').textContent = settings.fiscalYear;
    if (session.initialPassword) showToast('يرجى تغيير كلمة مرور المدير الافتراضية قبل الاستخدام الفعلي');
    liveDataReady = false;
    initialDataHydration = true;
    if (isModuleWindow) {
      document.body.classList.add('module-window');
      try { await window.ensureSarafaAssetsForView?.(moduleView); } catch (error) { view.innerHTML=`<section class="card"><h3>الأداة متوقفة لتخفيف الأداء</h3><p>${escapeHtml(error?.message||'فعّل الأداة من الإعدادات عند الحاجة.')}</p></section>`; return; }
      currentView=moduleView;
    } else render('dashboard');
    deferNonCriticalTask(async () => {
      const refreshed=await ensureLiveData();
      const needsRecovery=needsCoreDirectoryRecovery() || (requiresCustomerDirectories(currentView) && needsCustomerDirectoryRecovery());
      const directoriesRecovered=!needsRecovery || await refreshCoreDirectories(true);
      initialDataHydration=false;
      if (refreshed && (directoriesRecovered || !requiresCoreDirectories(currentView)) && (isModuleWindow || currentView === 'dashboard' || requiresCoreDirectories(currentView))) render(currentView);
      else if (isModuleWindow && requiresCoreDirectories(currentView)) view.innerHTML='<section class="card data-load-warning" role="alert"><div><b>تعذر تجهيز أدلة هذه النافذة.</b><span>لم تُفتح البيانات في نموذج فارغ، ولم يعدّل النظام أي سجل أو إعداد اتصال. افتح إعدادات النظام لنسخ تشخيص التحميل ثم أعد المحاولة.</span></div></section>';
      if (refreshed) refreshAlertCount();
    });
  } catch (error) {
    console.error('Startup failed after login', error);
    showLogin('تم قبول الدخول، لكن تعذر تحميل الواجهة. أغلق البرنامج ثم شغّله مجددًا.');
  }
}
async function submitLogin(event) {
  event.preventDefault();
  const response = await window.sarafa.dataCall('login', { username: document.getElementById('loginUsername').value, password: document.getElementById('loginPassword').value });
  if (!response.ok) { showLogin(response.error); return; }
  document.getElementById('loginPassword').value = '';
  await completeStartup(response.data);
}
