async function saveLoginConnection() {
  const status = document.getElementById('loginConnectionStatus');
  status.className = '';
  status.textContent = 'جارٍ حفظ واختبار الاتصال…';
  const database = { host: document.getElementById('loginDbHost').value.trim() || '127.0.0.1', port: Number(document.getElementById('loginDbPort').value || 3306), user: document.getElementById('loginDbUser').value.trim(), password: document.getElementById('loginDbPassword').value, database: document.getElementById('loginDbName').value.trim() || 'sarafa' };
  const fallback=async()=>{ settings = { ...settings, ...(await window.sarafa.getSettings()), database }; return window.sarafa.saveSettings(settings); };
  const saved=window.sarafa.saveLoginConnectionSettings ? await window.sarafa.saveLoginConnectionSettings(database) : await fallback();
  if (!saved?.ok) { status.className='error'; status.textContent=saved?.error || 'تعذر حفظ إعداد الاتصال المحمي'; return; }
  const result = await window.sarafa.dbStatus();
  if (result.connected) { status.className = 'success'; status.textContent = `تم الاتصال بقاعدة ${result.config.database} بنجاح`; document.getElementById('loginError').textContent = ''; }
  else { status.className = 'error'; status.textContent = 'تعذر الاتصال. تحقق من كلمة مرور MySQL والخدمة.'; }
  await refreshLoginConnectionStatus();
}
async function setupConnectionProtectionSettings() { if (currentView !== 'settings' || document.getElementById('connectionProtectionCard')) return; const target=document.getElementById('dbPassword')?.closest('.card'); if (!target) return; const result=await connectionProtectionStatus(); if (currentView !== 'settings' || document.getElementById('connectionProtectionCard')) return; const enabled=result?.enabled === true; const card=document.createElement('section'); card.className='card connection-protection-card'; card.id='connectionProtectionCard'; card.innerHTML=`<div class="card-title"><h3>حماية إعدادات اتصال MySQL</h3><span class="connection-protection-state ${enabled ? 'is-enabled' : 'is-disabled'}">${enabled ? '● مفعلة' : '● غير مفعلة'}</span></div><p class="muted">عند التفعيل، لا تظهر بيانات اتصال MySQL في نافذة الدخول ولا يمكن تعديلها إلا بكلمة حماية مستقلة يحددها مدير النظام.</p><div class="connection-protection-fields"><div class="field ${enabled ? '' : 'is-optional'}"><label>${enabled ? 'كلمة الحماية الحالية' : 'كلمة الحماية الجديدة'}</label><input id="connectionProtectionCurrent" type="password" autocomplete="new-password" placeholder="${enabled ? 'مطلوبة للتغيير أو الإيقاف' : '8 أحرف على الأقل'}"></div><div class="field"><label>${enabled ? 'كلمة حماية جديدة (اختياري)' : 'تأكيد كلمة الحماية'}</label><input id="connectionProtectionNew" type="password" autocomplete="new-password" placeholder="${enabled ? 'اتركها فارغة إن لم تغيّرها' : 'أعد كتابة كلمة الحماية'}"></div><div class="field"><label>${enabled ? 'تأكيد كلمة الحماية الجديدة' : 'تأكيد كلمة الحماية'}</label><input id="connectionProtectionConfirm" type="password" autocomplete="new-password" placeholder="أعد كتابة كلمة الحماية"></div></div><div class="connection-protection-actions"><button class="primary-btn" type="button" onclick="saveConnectionProtection('${enabled ? 'change' : 'enable'}')">${enabled ? 'حفظ التغيير' : 'تفعيل الحماية'}</button>${enabled ? '<button class="secondary-btn danger-quiet-btn" type="button" onclick="saveConnectionProtection(\'disable\')">إيقاف الحماية</button>' : ''}<span id="connectionProtectionStatus"></span></div>`; target.after(card); }
async function setupAdminMenuProtectionSettings() { if (currentView !== 'settings' || document.getElementById('adminMenuProtectionCard')) return; const anchor=document.getElementById('connectionProtectionCard') || document.getElementById('dbPassword')?.closest('.card'); if (!anchor) return; const result=window.sarafa.adminMenuProtectionStatus ? await window.sarafa.adminMenuProtectionStatus() : { ok:true, enabled:true }; if (currentView !== 'settings' || document.getElementById('adminMenuProtectionCard')) return; const enabled=result?.enabled !== false; const card=document.createElement('section'); card.className='card admin-menu-protection-card'; card.id='adminMenuProtectionCard'; card.innerHTML=`<div class="card-title"><h3>حماية قائمة الإدارة</h3><span class="admin-menu-protection-state ${enabled ? 'is-enabled' : 'is-disabled'}">${enabled ? '● مفعلة' : '● غير مفعلة'}</span></div><p class="muted">تمنع فتح أدوات الإدارة والإعدادات إلا بعد إدخال كلمة مرور مدير النظام. لا تغيّر هذه الحماية كلمة مرور تسجيل الدخول.</p>${enabled ? '<div class="field"><label>كلمة مرور المدير لإيقاف الحماية</label><input id="adminMenuProtectionPassword" type="password" autocomplete="current-password" placeholder="مطلوبة عند الإيقاف"></div>' : ''}<div class="admin-menu-protection-actions"><button class="${enabled ? 'secondary-btn danger-quiet-btn' : 'primary-btn'}" type="button" onclick="configureAdminMenuProtection('${enabled ? 'disable' : 'enable'}')">${enabled ? 'إيقاف حماية الإدارة' : 'تفعيل حماية الإدارة'}</button><span id="adminMenuProtectionStatus" role="status"></span></div>`; anchor.after(card); }
async function configureAdminMenuProtection(action) { const status=document.getElementById('adminMenuProtectionStatus'); if (status) { status.className=''; status.textContent='جارٍ حفظ إعداد حماية الإدارة…'; } const result=window.sarafa.configureAdminMenuProtection ? await window.sarafa.configureAdminMenuProtection({ action, password:String(document.getElementById('adminMenuProtectionPassword')?.value || '') }) : { ok:false, error:'هذه الميزة متاحة في الإصدار المثبت فقط' }; if (!result?.ok) { if (status) { status.className='error'; status.textContent=result?.error || 'تعذر حفظ حماية الإدارة'; } return; } showToast(result.enabled ? 'تم تفعيل حماية قائمة الإدارة' : 'تم إيقاف حماية قائمة الإدارة','success'); render('settings'); }
async function saveConnectionProtection(action) { const current=String(document.getElementById('connectionProtectionCurrent')?.value || ''); const next=String(document.getElementById('connectionProtectionNew')?.value || ''); const confirmPassword=String(document.getElementById('connectionProtectionConfirm')?.value || ''); const status=document.getElementById('connectionProtectionStatus'); if (action !== 'disable' && next !== confirmPassword) { if (status) { status.className='error'; status.textContent='تأكيد كلمة الحماية غير مطابق'; } return; } if (action !== 'disable' && next.length < 8) { if (status) { status.className='error'; status.textContent='استخدم كلمة حماية من 8 أحرف على الأقل'; } return; } if (status) { status.className=''; status.textContent='جارٍ حفظ الحماية…'; } const fallback=async()=>({ ok:false, error:'هذه الميزة متاحة في الإصدار المثبت فقط' }); const result=window.sarafa.configureConnectionProtection ? await window.sarafa.configureConnectionProtection({ action, currentPassword:current, newPassword:next }) : await fallback(); if (!result?.ok) { if (status) { status.className='error'; status.textContent=result?.error || 'تعذر حفظ حماية الاتصال'; } return; } showToast(result.enabled ? 'تم تفعيل حماية اتصال MySQL' : 'تم إيقاف حماية اتصال MySQL','success'); render('settings'); }
