function cashboxInventoryView() { const counts=(live.cashboxCounts || []).map((item) => `<tr><td>${escapeHtml(item.count_no)}</td><td>${escapeHtml(item.cashbox_name)}</td><td>${formatArabicDate(String(item.count_date).slice(0,10))}</td><td>${fmt(item.book_amount)}</td><td>${fmt(item.actual_amount)}</td><td>${fmt(item.variance_amount)}</td></tr>`).join(''); return `<div class="page-head"><div><h2>جرد الصناديق</h2><p>سجل جرد الصناديق وتسوية الفروقات في شاشة مستقلة.</p></div><div class="directory-page-actions"><button class="secondary-btn" onclick="navigate('cashboxes')">← دليل الصناديق</button><button class="primary-btn" onclick="navigate('cashbox-count')">＋ جرد صندوق</button></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>رقم الجرد</th><th>الصندوق</th><th>التاريخ</th><th>الرصيد الدفتري</th><th>العد الفعلي</th><th>الفرق</th></tr></thead><tbody>${counts || '<tr><td colspan="6">لا توجد عمليات جرد مسجلة بعد.</td></tr>'}</tbody></table></div></div>`; }
