function cashboxForm() { return `<div class="page-head"><div><h2>إضافة صندوق جديد</h2><p>ربط صندوق بحساب أصول لتستخدمه في السندات والعمليات</p></div><button class="secondary-btn" onclick="navigate('cashboxes')">← العودة لدليل الصناديق</button></div><div class="card"><div class="form-grid"><div class="field"><label>رقم الدليل التلقائي</label><input value="${cashboxNumberPreview()}" readonly></div><div class="field"><label>اسم الصندوق</label><input id="cashboxName" placeholder="مثال: الصندوق الرئيسي"></div><div class="field"><label>الحساب المحاسبي</label><select id="cashboxAccount">${selectOptions(live.accounts.filter((item) => item.account_type === 'asset'), 'id', (item) => `${item.code} — ${item.name_ar}`)}</select></div></div><div class="form-actions"><button class="primary-btn" onclick="saveCashbox()">حفظ الصندوق</button><button class="secondary-btn" onclick="navigate('cashboxes')">إلغاء</button></div></div>`; }
function cashboxEditor() { const item=live.cashboxes.find((cashbox)=>Number(cashbox.id)===Number(editingCashboxId)); if (!item) return '<div class="card">الصندوق المطلوب غير موجود.</div>'; return `<div class="page-head"><div><h2>تعديل صندوق</h2><p>مدير النظام يستطيع تعديل الاسم والحساب المرتبط أو حالة الصندوق.</p></div><button class="secondary-btn" onclick="navigate('cashboxes')">← العودة لدليل الصناديق</button></div><div class="card"><div class="form-grid"><div class="field"><label>رقم الدليل</label><input value="${escapeHtml(String(item.cashbox_no || item.id))}" readonly></div><div class="field"><label>اسم الصندوق</label><input id="editCashboxName" value="${escapeHtml(item.name_ar)}"></div><div class="field"><label>الحساب المحاسبي</label><select id="editCashboxAccount">${selectOptions(live.accounts.filter((account)=>account.account_type==='asset'), 'id', (account)=>`${account.code} — ${account.name_ar}`, item.account_id)}</select></div><div class="field"><label><input id="editCashboxActive" type="checkbox" ${item.active ? 'checked' : ''}> الصندوق نشط</label></div></div><div class="form-actions"><button class="primary-btn" onclick="saveCashboxEdit(${item.id})">حفظ التعديل</button><button class="danger-btn" onclick="deleteCashbox(${item.id})">حذف الصندوق</button><button class="secondary-btn" onclick="navigate('cashboxes')">إلغاء</button></div></div>`; }
function settingsView() { const db = settings.database || {}; const users = live.users.map((item) => `<tr><td>${escapeHtml(item.username)}</td><td>${escapeHtml(item.display_name)}</td><td>${escapeHtml(item.role_name)}</td><td>${item.last_login ? String(item.last_login).slice(0,16) : '—'}</td><td>${badge(item.active ? 'نشط' : 'موقوف')}</td></tr>`).join(''); return `<div class="page-head"><div><h2>إعدادات النظام والصلاحيات</h2><p>تهيئة المنشأة وMySQL والمستخدمين من قاعدة البيانات</p></div><button class="primary-btn" onclick="saveSettings()">حفظ الإعدادات</button></div><div class="card"><div class="form-grid"><div class="field"><label>اسم المنشأة</label><input id="company" value="${escapeHtml(settings.company || 'مؤسسة الصرافة الحديثة')}"></div><div class="field"><label>اسم الفرع</label><input id="branch" value="${escapeHtml(settings.branch)}"></div><div class="field"><label>العملة الأساسية</label><select id="currency"><option ${settings.baseCurrency === 'ريال يمني' ? 'selected' : ''}>ريال يمني</option><option>دولار أمريكي</option><option>ريال سعودي</option></select></div><div class="field"><label>السنة المالية</label><input id="year" type="number" value="${escapeHtml(settings.fiscalYear)}"></div><div class="field"><label>طريقة التاريخ</label><select id="dateMode"><option ${settings.dateMode !== 'manual' ? 'selected' : ''}>تلقائي</option><option ${settings.dateMode === 'manual' ? 'selected' : ''}>يدوي</option></select></div></div></div><div class="card" style="margin-top:18px"><div class="card-title"><h3>اتصال MySQL المحلي</h3><button class="secondary-btn" onclick="testDatabase()">اختبار الاتصال</button></div><p class="muted">تحفظ الإعدادات محليًا في بيانات مستخدم Windows ولا تُضمَّن في ملف EXE.</p><div class="form-grid"><div class="field"><label>الخادم</label><input id="dbHost" value="${escapeHtml(db.host || '127.0.0.1')}"></div><div class="field"><label>المنفذ</label><input id="dbPort" type="number" value="${db.port || 3306}"></div><div class="field"><label>اسم المستخدم</label><input id="dbUser" value="${escapeHtml(db.user || 'sarafa_user')}"></div><div class="field"><label>كلمة المرور</label><input id="dbPassword" type="password" value="${escapeHtml(db.password || '')}"></div><div class="field"><label>اسم قاعدة البيانات</label><input id="dbName" value="${escapeHtml(db.database || 'sarafa')}"></div></div></div><div class="card" style="margin-top:18px"><div class="card-title"><h3>المستخدمون والمجموعات</h3><button class="primary-btn" onclick="navigate('new-user')">＋ مستخدم جديد</button></div><div class="table-wrap"><table class="data-table"><thead><tr><th>اسم المستخدم</th><th>الاسم الظاهر</th><th>المجموعة</th><th>آخر دخول</th><th>الحالة</th></tr></thead><tbody>${users || '<tr><td colspan="5">لا يوجد مستخدمون.</td></tr>'}</tbody></table></div></div>`; }
function userForm() { return `<div class="page-head"><div><h2>إضافة مستخدم جديد</h2><p>تُحفظ كلمة المرور كتجزئة في MySQL ولا تُعرض لاحقًا</p></div><button class="secondary-btn" onclick="navigate('settings')">← العودة للإعدادات</button></div><div class="card"><div class="form-grid"><div class="field"><label>اسم المستخدم</label><input id="newUsername" placeholder="مثال: accountant"></div><div class="field"><label>الاسم الظاهر</label><input id="newDisplayName" placeholder="اسم الموظف"></div><div class="field"><label>المجموعة</label><input id="newRoleName" value="المحاسبون"></div><div class="field"><label>كلمة المرور</label><input id="newUserPassword" type="password" placeholder="8 أحرف على الأقل"></div></div><div class="form-actions"><button class="primary-btn" onclick="saveUser()">حفظ المستخدم</button><button class="secondary-btn" onclick="navigate('settings')">إلغاء</button></div></div>`; }
function userAccessView() { const rows = live.users.map((item) => `<tr><td>${escapeHtml(item.username)}</td><td>${escapeHtml(item.display_name)}</td><td>${escapeHtml(item.role_name)}</td><td>${badge(item.active ? 'نشط' : 'محجوب')}</td><td><button class="access-toggle-btn ${item.active ? 'is-active' : 'is-blocked'}" onclick="toggleUser(${item.id}, ${item.active ? 'false' : 'true'})"><span aria-hidden="true">${item.active ? '⊘' : '✓'}</span>${item.active ? 'حجب' : 'تفعيل'}</button></td></tr>`).join(''); const modules='<option value="accounts">الحسابات والقيود</option><option value="vouchers">السندات</option><option value="transfers">الحوالات</option><option value="exchange">الصرافة</option><option value="cashboxes">الصناديق والجرد</option><option value="customers">العملاء والوكلاء</option><option value="employees">الموظفون</option><option value="reports">التقارير ولوحة التحكم</option><option value="audit">الأرشيف والسجل السري</option><option value="settings">الإدارة والإعدادات</option><option value="print-designer">مصمم الطباعة</option><option value="layout-controls">مصممو الواجهة والنوافذ</option>'; return `<div class="report-single-title access-single-title"><h2>المستخدمون والصلاحيات</h2></div><div class="report-single-actions access-actions"><button class="primary-btn user-create-btn" onclick="navigate('new-user')"><span aria-hidden="true">＋</span> مستخدم جديد</button></div><div class="table-wrap"><table class="data-table"><thead><tr><th>المستخدم</th><th>الاسم</th><th>المجموعة</th><th>الحالة</th><th>إجراء</th></tr></thead><tbody>${rows || '<tr><td colspan="5">لا يوجد مستخدمون.</td></tr>'}</tbody></table></div><div class="card access-permission-card" style="margin-top:18px"><div class="card-title access-card-title"><span class="access-card-icon" aria-hidden="true">◫</span><div><h3>صلاحية وحدة</h3><small>الأرشيف السري يبقى محميًا كذلك بشرط مدير النظام.</small></div></div><div class="form-grid"><div class="field"><label>المستخدم</label><select id="permissionUser">${selectOptions(live.users, 'id', (item) => `${item.username} — ${item.display_name}`)}</select></div><div class="field"><label>الوحدة</label><select id="permissionModule">${modules}</select></div></div><div class="form-grid" style="margin-top:10px"><label class="access-permission-toggle"><input id="permView" type="checkbox" checked><span aria-hidden="true">◉</span>عرض</label><label class="access-permission-toggle"><input id="permAdd" type="checkbox"><span aria-hidden="true">＋</span>إضافة</label><label class="access-permission-toggle"><input id="permEdit" type="checkbox"><span aria-hidden="true">✎</span>تعديل</label><label class="access-permission-toggle"><input id="permDelete" type="checkbox"><span aria-hidden="true">×</span>حذف</label><label class="access-permission-toggle"><input id="permPost" type="checkbox"><span aria-hidden="true">↑</span>ترحيل</label><label class="access-permission-toggle"><input id="permPrint" type="checkbox"><span aria-hidden="true">▤</span>طباعة</label></div><div class="form-actions"><button class="primary-btn" onclick="savePermission()">حفظ الصلاحية</button></div></div>`; }
function groupsView() { const groups = live.groups.map((item) => `<tr><td>${escapeHtml(item.group_name)}</td><td>${escapeHtml(item.description_ar || '—')}</td><td>${badge(item.active ? 'نشطة' : 'موقوفة')}</td></tr>`).join(''); const modules='<option value="accounts">الحسابات والقيود</option><option value="vouchers">السندات</option><option value="transfers">الحوالات</option><option value="exchange">الصرافة</option><option value="cashboxes">الصناديق والجرد</option><option value="customers">العملاء والوكلاء</option><option value="employees">الموظفون</option><option value="reports">التقارير ولوحة التحكم</option><option value="audit">الأرشيف والسجل السري</option><option value="settings">الإدارة والإعدادات</option><option value="print-designer">مصمم الطباعة</option><option value="layout-controls">مصممو الواجهة والنوافذ</option>'; return `<div class="page-head"><div><h2>مجموعات الصلاحيات</h2><p>تحديد أدوار موحدة وصلاحيات تفصيلية لوحدات العمل المحلية.</p></div></div><div class="grid-2"><div class="card"><div class="card-title"><h3>إضافة مجموعة</h3></div><div class="field"><label>اسم المجموعة</label><input id="groupName" placeholder="مثال: محاسبو الفروع"></div><div class="field" style="margin-top:12px"><label>الوصف</label><input id="groupDescription"></div><div class="form-actions"><button class="primary-btn" onclick="saveUserGroup()">حفظ المجموعة</button></div></div><div class="card"><div class="card-title"><h3>صلاحية المجموعة</h3></div><div class="form-grid"><div class="field"><label>المجموعة</label><select id="groupPermissionId">${selectOptions(live.groups, 'id', (item) => item.group_name)}</select></div><div class="field"><label>الوحدة</label><select id="groupPermissionModule">${modules}</select></div></div><div class="form-grid" style="margin-top:10px"><label><input id="groupPermView" type="checkbox" checked> عرض</label><label><input id="groupPermAdd" type="checkbox"> إضافة</label><label><input id="groupPermEdit" type="checkbox"> تعديل</label><label><input id="groupPermDelete" type="checkbox"> حذف</label><label><input id="groupPermPost" type="checkbox"> ترحيل</label><label><input id="groupPermPrint" type="checkbox"> طباعة</label></div><div class="form-actions"><button class="primary-btn" onclick="saveGroupPermissions()">حفظ الصلاحية</button></div></div></div><div class="table-wrap" style="margin-top:18px"><table class="data-table"><thead><tr><th>المجموعة</th><th>الوصف</th><th>الحالة</th></tr></thead><tbody>${groups || '<tr><td colspan="3">لا توجد مجموعات مخصصة بعد.</td></tr>'}</tbody></table></div>`; }
function deviceAccessView() { return `<div class="page-head"><div><h2>أجهزة المستخدمين</h2><p>اعتماد جهاز محلي للمستخدم وتقييد تسجيل دخوله على الأجهزة المعتمدة</p></div></div><div class="card"><div class="form-grid"><div class="field"><label>المستخدم</label><select id="deviceUser">${selectOptions(live.users, 'id', (item) => `${item.username} — ${item.display_name}`)}</select></div><div class="field"><label>اسم الجهاز</label><input id="deviceName" placeholder="مثال: PC-CASHIER-01"></div><div class="field"><label><input id="deviceAllowed" type="checkbox" checked> الجهاز معتمد</label><label style="margin-top:14px"><input id="deviceRestricted" type="checkbox"> قصر دخول المستخدم على الأجهزة المعتمدة</label></div></div><div class="form-actions"><button class="primary-btn" onclick="saveDeviceAccess()">حفظ اعتماد الجهاز</button></div></div>`; }
function passwordView() { return `<div class="page-head"><div><h2>تغيير كلمة المرور</h2><p>تغيير كلمة مرور المستخدم الحالي محليًا مع حفظ تجزئة آمنة في MySQL</p></div></div><div class="card"><div class="form-grid"><div class="field"><label>كلمة المرور الحالية</label><input id="currentPassword" type="password" autocomplete="current-password"></div><div class="field"><label>كلمة المرور الجديدة</label><input id="newPassword" type="password" autocomplete="new-password"></div><div class="field"><label>تأكيد كلمة المرور الجديدة</label><input id="confirmPassword" type="password" autocomplete="new-password"></div></div><div class="form-actions"><button class="primary-btn" onclick="saveOwnPassword()">حفظ كلمة المرور الجديدة</button></div></div>`; }
const shortcutDocuments = { 'quick-entry':'الإدخال السريع', 'voucher-receipt':'سند قبض', 'voucher-payment':'سند صرف', 'transfers-incoming':'حوالة واردة', 'transfers-outgoing':'حوالة صادرة', 'exchange-buy':'شراء عملات', 'exchange-sell':'بيع عملات', 'simple-entries':'قيد بسيط', 'account-statement':'كشف حساب', reports:'التقارير' };
const shortcutActions = { save:'حفظ وإضافة', create:'عملية جديدة', print:'معاينة وطباعة', refresh:'تحديث الشاشة', close:'خروج من النافذة' };
const shortcutKeys = ['F2','F4','F9','Ctrl+P','Esc'];
function shortcutManagerView() { const bindings=settings.shortcutBindings || {}; const rows=Object.entries(shortcutDocuments).flatMap(([documentKey,documentName]) => shortcutKeys.map((key) => `<tr><td>${documentName}</td><td>${key}</td><td>${shortcutActions[bindings?.[documentKey]?.[key]] || 'الافتراضي'}</td></tr>`)).join(''); return `<div class="page-head"><div><h2>إدارة الاختصارات</h2><p>اختر المستند والاختصار والوظيفة. تُرفض الاختصارات غير المعتمدة أو المتعارضة داخل المستند نفسه.</p></div></div><section class="card"><div class="form-grid"><div class="field"><label>نوع المستند</label><select id="shortcutDocument">${Object.entries(shortcutDocuments).map(([key,label]) => `<option value="${key}">${label}</option>`).join('')}</select></div><div class="field"><label>الاختصار</label><select id="shortcutKey">${shortcutKeys.map((key) => `<option value="${key}">${key}</option>`).join('')}</select></div><div class="field"><label>الوظيفة</label><select id="shortcutAction">${Object.entries(shortcutActions).map(([key,label]) => `<option value="${key}">${label}</option>`).join('')}</select></div></div><div class="form-actions"><button class="primary-btn" onclick="saveShortcutBinding()">حفظ الربط</button><button class="secondary-btn" onclick="restoreShortcutDefaults()">استعادة الافتراضيات</button></div></section><section class="card" style="margin-top:18px"><div class="card-title"><h3>الاختصارات الحالية</h3></div><div class="table-wrap"><table class="data-table"><thead><tr><th>المستند</th><th>الاختصار</th><th>الوظيفة</th></tr></thead><tbody>${rows}</tbody></table></div></section>`; }
async function saveShortcutBinding() { const documentKey=document.getElementById('shortcutDocument')?.value; const key=document.getElementById('shortcutKey')?.value; const action=document.getElementById('shortcutAction')?.value; if (!shortcutDocuments[documentKey] || !shortcutKeys.includes(key) || !shortcutActions[action]) { showToast('اختر مستندًا واختصارًا ووظيفة صحيحة'); return; } settings.shortcutBindings={ ...(settings.shortcutBindings || {}), [documentKey]:{ ...(settings.shortcutBindings?.[documentKey] || {}), [key]:action } }; await window.sarafa.saveSettings(settings); showToast(`تم ربط ${key} بوظيفة ${shortcutActions[action]} في ${shortcutDocuments[documentKey]}`); render('shortcut-manager'); }
async function restoreShortcutDefaults() { settings.shortcutBindings={}; await window.sarafa.saveSettings(settings); showToast('تمت استعادة اختصارات النظام الافتراضية'); render('shortcut-manager'); }
function shortcutKeyFromEvent(event) { if (event.ctrlKey && event.key.toLowerCase() === 'p') return 'Ctrl+P'; if (event.key === 'Escape') return 'Esc'; return ['F2','F4','F9'].includes(event.key) ? event.key : ''; }
function runShortcutAction(action) { if (action === 'save') { const save=view.querySelector('.operation-command-bar .primary-btn,.voucher-actions .primary-btn,.quick-entry-actions .primary-btn,.form-actions .primary-btn'); if (save) save.click(); return true; } if (action === 'create') { const targets={ 'voucher-receipt':'voucher-receipt','voucher-payment':'voucher-payment','transfers-incoming':'new-transfer-incoming','transfers-outgoing':'new-transfer-outgoing','exchange-buy':'new-exchange-buy','exchange-sell':'new-exchange-sell','simple-entries':'new-simple-entry','quick-entry':'quick-entry' }; if (targets[currentView]) { navigate(targets[currentView]); return true; } } if (action === 'print') { previewPrint(); return true; } if (action === 'refresh') { navigate(currentView); return true; } if (action === 'close') { closeActiveWindow(); return true; } return false; }
window.saveShortcutBinding = saveShortcutBinding;
window.restoreShortcutDefaults = restoreShortcutDefaults;
const basePasswordView = passwordView;
passwordView = function() { return `${basePasswordView()}<section class="card" style="margin-top:18px"><div class="card-title"><h3>بريد استعادة مدير النظام</h3></div><p class="muted">أدخل بيانات SMTP وبريد المدير. تُشفّر كلمة مرور التطبيق بواسطة حماية Windows ولا تُعرض بعد الحفظ.</p><div class="form-grid"><div class="field"><label>خادم البريد SMTP</label><input id="recoveryMailHost" placeholder="smtp.example.com"></div><div class="field"><label>المنفذ</label><input id="recoveryMailPort" type="number" value="587"></div><div class="field"><label>بريد المدير المستلم</label><input id="recoveryMailFrom" type="email" placeholder="manager@example.com"></div><div class="field"><label>اسم مستخدم SMTP</label><input id="recoveryMailUsername" autocomplete="username"></div><div class="field"><label>كلمة مرور التطبيق</label><input id="recoveryMailPassword" type="password" autocomplete="new-password"></div><div class="field"><label><input id="recoveryMailSecure" type="checkbox"> اتصال TLS مباشر (عادة للمنفذ 465)</label></div></div><div class="form-actions"><button class="primary-btn" onclick="configureRecoveryEmail()">حفظ بريد الاستعادة</button></div></section>`; };
async function configureRecoveryEmail() { const result=await window.sarafa.configureRecoveryEmail({ host:document.getElementById('recoveryMailHost')?.value, port:document.getElementById('recoveryMailPort')?.value, from:document.getElementById('recoveryMailFrom')?.value, username:document.getElementById('recoveryMailUsername')?.value, password:document.getElementById('recoveryMailPassword')?.value, secure:document.getElementById('recoveryMailSecure')?.checked }); showToast(result.ok ? `تم حفظ بريد الاستعادة: ${result.from}` : result.error || 'تعذر حفظ بريد الاستعادة'); if (result.ok) document.getElementById('recoveryMailPassword').value=''; }
async function openManagerPasswordRecovery() { const requested=await window.sarafa.requestManagerPasswordRecovery(); if (!requested.ok) { document.getElementById('loginError').textContent=requested.error || 'تعذر طلب رمز الاستعادة'; return; } const existing=document.getElementById('managerRecoveryModal'); if (existing) existing.remove(); const modal=document.createElement('div'); modal.id='managerRecoveryModal'; modal.className='print-preview-modal'; modal.innerHTML=`<section class="card" style="width:min(500px,92vw);margin:auto"><div class="card-title"><h3>تعيين كلمة مرور مدير جديدة</h3></div><p class="muted">أُرسل رمز صالح لمدة 15 دقيقة إلى بريد المدير المعتمد.</p><div class="form-grid"><div class="field"><label>رمز الاستعادة</label><input id="managerRecoveryCode" inputmode="numeric" maxlength="6" autocomplete="one-time-code"></div><div class="field"><label>كلمة المرور الجديدة</label><input id="managerRecoveryNewPassword" type="password" autocomplete="new-password"></div><div class="field"><label>تأكيد كلمة المرور الجديدة</label><input id="managerRecoveryConfirm" type="password" autocomplete="new-password"></div></div><div class="form-actions"><button class="primary-btn" onclick="completeManagerPasswordRecovery()">تعيين كلمة المرور</button><button class="secondary-btn" onclick="document.getElementById('managerRecoveryModal')?.remove()">إلغاء</button></div></section>`; document.body.appendChild(modal); }
async function completeManagerPasswordRecovery() { const password=document.getElementById('managerRecoveryNewPassword')?.value || ''; if (password !== (document.getElementById('managerRecoveryConfirm')?.value || '')) { showToast('تأكيد كلمة المرور غير مطابق'); return; } const result=await window.sarafa.completeManagerPasswordRecovery({ code:document.getElementById('managerRecoveryCode')?.value, newPassword:password }); if (!result.ok) { showToast(result.error || 'تعذر تعيين كلمة المرور'); return; } document.getElementById('managerRecoveryModal')?.remove(); document.getElementById('loginPassword').value=''; document.getElementById('loginError').textContent='تم تعيين كلمة مرور المدير الجديدة. يمكنك تسجيل الدخول الآن.'; }
window.configureRecoveryEmail = configureRecoveryEmail;
window.completeManagerPasswordRecovery = completeManagerPasswordRecovery;
function employeesView() { const rows = live.employees.map((item) => `<tr><td>${item.employee_no}</td><td>${escapeHtml(item.full_name)}</td><td>${escapeHtml(item.job_title || '—')}</td><td>${fmt(item.monthly_salary)}</td><td>${escapeHtml(item.account_name || '—')}</td><td>${badge(item.active ? 'نشط' : 'محجوب')}</td></tr>`).join(''); return `<div class="page-head"><div><h2>دليل الموظفين</h2><p>ربط الموظف بحسابه المالي ومكوّن راتبه</p></div><button class="primary-btn" onclick="navigate('new-employee')">＋ موظف جديد</button></div><div class="table-wrap"><table class="data-table"><thead><tr><th>الرقم</th><th>الموظف</th><th>المهنة</th><th>الراتب</th><th>الحساب المالي</th><th>الحالة</th></tr></thead><tbody>${rows || '<tr><td colspan="6">لا يوجد موظفون بعد.</td></tr>'}</tbody></table></div>`; }
function employeeForm() { return `<div class="page-head"><div><h2>إضافة موظف</h2><p>بيانات الموظف والحساب المالي والراتب</p></div><button class="secondary-btn" onclick="navigate('employees')">← العودة</button></div><div class="card"><div class="form-grid"><div class="field"><label>اسم الموظف</label><input id="employeeName" placeholder="الاسم الكامل"></div><div class="field"><label>الهاتف</label><input id="employeePhone"></div><div class="field"><label>المهنة</label><input id="employeeJob" placeholder="مثال: محاسب"></div><div class="field"><label>الراتب الشهري</label><input id="employeeSalary" type="number" value="0"></div><div class="field"><label>الحساب المالي</label><select id="employeeAccount">${selectOptions(live.accounts.filter((item) => item.active), 'id', (item) => `${item.code} — ${item.name_ar}`)}</select></div></div><div class="form-actions"><button class="primary-btn" onclick="saveEmployee()">حفظ الموظف</button><button class="secondary-btn" onclick="navigate('employees')">إلغاء</button></div></div>`; }
function transferForm(initialType = '') {
  const fixedType = ['incoming', 'outgoing'].includes(initialType) ? initialType : '';
  const title = fixedType === 'incoming' ? 'حوالة واردة' : fixedType === 'outgoing' ? 'حوالة صادرة' : 'حوالة جديدة';
  const transferTypeField = fixedType ? `<input id="transferType" type="hidden" value="${fixedType}">` : `<div class="field"><label>نوع الحوالة</label><select id="transferType"><option value="outgoing">حوالة صادرة</option><option value="incoming">حوالة واردة</option></select></div>`;
  const showTransferCommission = fixedType !== 'incoming';
  const transferCommissionField = showTransferCommission ? `<div class="field"><label>العمولة</label><input id="transferCommission" type="number" value="0"></div>` : '';
  const transferTypeCell = (item) => fixedType ? '' : `<td>${item.transfer_type === 'incoming' ? 'واردة' : 'صادرة'}</td>`;
  const transferTypeHeader = fixedType ? '' : '<th>النوع</th>';
  const transferCommissionCell = (item) => showTransferCommission ? `<td>${fmt(item.commission || 0)}</td>` : '';
  const transferCommissionHeader = showTransferCommission ? '<th>العمولة</th>' : '';
  const transferColumnCount = fixedType === 'incoming' ? 13 : fixedType ? 14 : 15;
  const todayRows = live.transfers.filter((item) => (!fixedType || item.transfer_type === fixedType) && matchesOperationDate(item,'transfer_date')).map((item) => `<tr class="operation-row transfer-${item.transfer_type}"><td>${escapeHtml(item.transfer_no)}</td>${transferTypeCell(item)}<td>${escapeHtml(item.sender_name || '—')}</td><td>${escapeHtml(item.sender_phone || '—')}</td><td>${escapeHtml(item.beneficiary_name || '—')}</td><td>${escapeHtml(item.beneficiary_phone || '—')}</td><td>${escapeHtml(item.agent_name || '—')}</td><td>${escapeHtml(item.cashbox_name || '—')}</td><td>${escapeHtml(item.counter_account_name || '—')}</td><td>${escapeHtml(item.currency_code || '—')}</td><td>${fmt(item.amount)}</td>${transferCommissionCell(item)}<td>${escapeHtml(item.notes || '—')}</td><td>${operationDateTime(item.created_at || item.transfer_date)}</td><td>${badge(item.status === 'pending' ? 'قيد الانتظار' : item.status === 'completed' ? 'مكتملة' : 'ملغاة')}</td></tr>`).join('');
  const transferNumber=nextNumericPreview(live.transfers,'transfer_no');
  return `<div class="page-head"><div><h2>${title}</h2><p>إنشاء حوالة صادرة أو واردة مع احتساب العمولة والقيد المحاسبي</p></div><button class="secondary-btn" onclick="navigate('transfers')">← العودة للحوالات</button></div><div class="card"><div class="form-grid">
    ${transferTypeField}<div class="field"><label>رقم الحوالة التلقائي</label><input id="transferNumber" value="${transferNumber}" readonly></div><div class="field"><label>العملة</label><select id="transferCurrency">${selectOptions(live.currencies.filter((item) => item.active), 'id', (item) => `${item.name_ar} (${item.code})`)}</select></div><div class="field"><label>المبلغ</label><input id="transferAmount" type="number" placeholder="0.00"></div>
    <div class="field"><label>اسم المرسل</label><input id="senderName" placeholder="الاسم الكامل"></div><div class="field"><label>هاتف المرسل</label><input id="senderPhone" placeholder="رقم الهاتف"></div><div class="field"><label>اسم المستفيد</label><input id="beneficiaryName" placeholder="الاسم الكامل"></div>
    <div class="field"><label>هاتف المستفيد</label><input id="beneficiaryPhone" placeholder="رقم الهاتف"></div><div class="field"><label>الوكيل</label><select id="transferAgent">${selectOptions(live.customers.filter((item) => item.customer_type === 'agent' && item.active), 'id', (item) => item.full_name)}</select></div>${transferCommissionField}
    <div class="field"><label>الصندوق</label><select id="transferCashbox">${selectOptions(live.cashboxes.filter((item) => item.active && item.account_id), 'id', (item) => item.name_ar)}</select></div><div class="field"><label>الحساب المقابل</label><select id="transferCounterAccount">${selectOptions(live.accounts.filter((item) => item.active), 'id', operationAccountName)}</select></div>
    <div class="field" style="grid-column:1/-1"><label>البيان والملاحظات</label><textarea id="transferNotes" placeholder="أضف أي ملاحظات مرتبطة بالحوالة..."></textarea></div>
  </div><div class="form-actions"><button class="primary-btn" onclick="saveTransfer()">حفظ الحوالة</button><button class="secondary-btn" onclick="saveTransfer(true)">حفظ وطباعة</button><button class="secondary-btn" onclick="navigate('transfers')">إلغاء</button></div></div><section class="daily-operations-panel">${dailyOperationsFilter('عرض عمليات الحوالات حسب التاريخ')}<div class="daily-operations-title"><strong>${title}</strong><span>${todayRows ? 'تظهر آخر عملية أولًا' : 'لا توجد عمليات لهذا التاريخ'}</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>رقم الحوالة</th>${transferTypeHeader}<th>المرسل</th><th>هاتف المرسل</th><th>المستفيد</th><th>هاتف المستفيد</th><th>الوكيل</th><th>الصندوق</th><th>الحساب</th><th>العملة</th><th>المبلغ</th>${transferCommissionHeader}<th>الملاحظة</th><th>وقت التنفيذ</th><th>الحالة</th></tr></thead><tbody>${todayRows || `<tr><td colspan="${transferColumnCount}">لا توجد عمليات لهذا اليوم.</td></tr>`}</tbody></table></div></section>`;
}
