function currencySettings() {
  const body = live.currencies.map((item) => `<tr><td>${escapeHtml(item.code)}</td><td>${escapeHtml(item.name_ar)}</td><td><input class="currency-rate-input" id="rate-transfer-${item.id}" value="${Number(item.transfer_rate || 0)}"></td><td><input class="currency-rate-input" id="rate-buy-${item.id}" value="${Number(item.buy_rate || 0)}"></td><td><input class="currency-rate-input" id="rate-sell-${item.id}" value="${Number(item.sell_rate || 0)}"></td><td>${badge(item.active ? 'نشطة' : 'موقوفة')}</td><td><div class="currency-actions"><button class="primary-btn mini-btn" onclick="saveCurrencyRates(${item.id})">حفظ</button><button class="secondary-btn mini-btn" onclick="editCurrency(${item.id})">تفاصيل</button><button class="${item.active ? 'danger-btn' : 'secondary-btn'} mini-btn" onclick="toggleCurrencyActive(${item.id}, ${item.active ? 'false' : 'true'})">${item.active ? 'إيقاف' : 'تفعيل'}</button></div></td></tr>`).join('');
  return `<div class="window-command-line"><span>دليل العملات — تعديل يدوي مباشر للأسعار</span><button class="primary-btn mini-btn" onclick="navigate('new-currency')">＋ إضافة عملة</button></div><div class="toolbar"><input class="search" oninput="filterRows(this)" aria-label="بحث باسم العملة أو الرمز"><button class="secondary-btn" onclick="navigate('currency-settings')">تحديث الأسعار</button></div><div class="table-wrap"><table class="data-table"><thead><tr><th>الرمز</th><th>اسم العملة</th><th>التحويل</th><th>الشراء</th><th>البيع</th><th>الحالة</th><th>إجراء</th></tr></thead><tbody>${body || '<tr><td colspan="7">لا توجد عملات.</td></tr>'}</tbody></table></div>`;
}
