const fullExchangeForm = exchangeForm;
exchangeForm = function(initialType = '') {
  const operationType = initialType === 'buy' ? 'buy' : 'sell';
  const firstForeignCurrency = live.currencies.find((item) => item.active && !item.is_base);
  const defaultRate = rateForCurrency(firstForeignCurrency?.id, operationType) || '';
  return fullExchangeForm(initialType)
    .replace(/<div class="field"><label>نوع العملية<\/label><select id="exchangeType"[\s\S]*?<\/select><\/div>/, `<input id="exchangeType" type="hidden" value="${operationType}">`)
    .replace(/<div class="field"><label>المناولة \/ العمولة<\/label><input id="handling"[\s\S]*?<\/div>/, '')
    .replace(/سعر العملية/g, 'سعر الصرف')
    .replace('<select id="exchangeCurrency">', '<select id="exchangeCurrency" onchange="applyExchangeDefaultRate()">')
    .replace(/(<input id="foreignAmount"[^>]*?) value="0"/, '$1')
    .replace(/<div class="field"><label>سعر التحويل<\/label><input id="transferRate"[^>]*><\/div>/, '')
    .replace(/(<input id="dealRate"[^>]*?) value="0"/, `$1 value="${defaultRate}"`)
    .replace(/(<input id="localAmount"[^>]*?) value="0\.00"/, '$1');
};
function calculateExchange() {
  const amount = Number(document.getElementById('foreignAmount')?.value || 0);
  const rate = Number(document.getElementById('dealRate')?.value || 0);
  const type = document.getElementById('exchangeType')?.value || 'sell';
  const currency = live.currencies.find((item) => String(item.id) === String(document.getElementById('exchangeCurrency')?.value));
  const defaultRate = rateForCurrency(currency?.id, type);
  const local = amount * rate;
  const target = document.getElementById('localAmount');
  if (target) target.value = local.toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});
  const localText = document.getElementById('exchangeCalcLocal');
  const rateText = document.getElementById('exchangeCalcRate');
  const currencyText = document.getElementById('exchangeCalcCurrency');
  const difference = document.getElementById('exchangeCalcDifference');
  const status = document.getElementById('exchangeCalcStatus');
  if (localText) localText.textContent = fmt(local);
  if (rateText) rateText.textContent = fmt(rate);
  if (currencyText) currencyText.textContent = currency ? `${currency.name_ar} (${currency.code}) — المقابل المحلي` : 'اختر العملة والسعر';
  const delta = rate - defaultRate;
  if (difference) difference.textContent = currency && defaultRate ? `سعر الدليل ${fmt(defaultRate)} · فرق ${delta >= 0 ? '+' : ''}${fmt(delta)}` : 'لا يوجد سعر دليل بعد';
  let warning = '';
  if (!amount || amount <= 0) warning = 'أدخل مبلغًا صحيحًا أكبر من صفر';
  else if (!rate || rate <= 0) warning = 'أدخل سعر صرف صحيحًا';
  else if (type === 'buy' && currency?.min_buy_rate != null && rate < Number(currency.min_buy_rate)) warning = `السعر أقل من الحد الأدنى المعتمد: ${fmt(currency.min_buy_rate)}`;
  else if (type === 'sell' && currency?.max_sell_rate != null && rate > Number(currency.max_sell_rate)) warning = `السعر أعلى من الحد الأقصى المعتمد: ${fmt(currency.max_sell_rate)}`;
  if (status) { status.textContent = warning || `المقابل المحلي ${fmt(local)}`; status.classList.toggle('warning',Boolean(warning)); }
}
function saveExchange() {
  const operationType = document.getElementById('exchangeType')?.value || 'sell';
  const amount = Number(document.getElementById('foreignAmount')?.value || 0);
  const rate = Number(document.getElementById('dealRate')?.value || 0);
  const currency = live.currencies.find((item) => String(item.id) === String(document.getElementById('exchangeCurrency')?.value));
  if (!amount || !rate) { showToast('تحقق من المبلغ وسعر الصرف قبل الحفظ'); return; }
  if (operationType === 'buy' && currency?.min_buy_rate != null && rate < Number(currency.min_buy_rate)) { showToast(`السعر أقل من الحد الأدنى المعتمد: ${fmt(currency.min_buy_rate)}`); return; }
  if (operationType === 'sell' && currency?.max_sell_rate != null && rate > Number(currency.max_sell_rate)) { showToast(`السعر أعلى من الحد الأقصى المعتمد: ${fmt(currency.max_sell_rate)}`); return; }
  saveRecord('createExchange', { operationType, currencyId: document.getElementById('exchangeCurrency').value, cashboxId: document.getElementById('exchangeCashbox').value, counterAccountId: document.getElementById('exchangeCounterAccount').value, customerId: document.getElementById('exchangeCustomer').value || null, operationDate: document.getElementById('exchangeDate').value, amount, transferRate: document.getElementById('transferRate').value || rate, dealRate:rate, handlingFee:0, notes: document.getElementById('exchangeNotes').value }, operationType === 'buy' ? 'exchange-buy' : 'exchange-sell', 'تم حفظ وترحيل عملية الصرافة والقيد');
}
