function setupExchangeWorkbench() { const card=view.querySelector('.reference-operation-view > .card,.daily-operation-workbench > .card,.card'); if (!card || document.getElementById('exchangeCalculator')) return; card.classList.add('exchange-workbench-card'); const calculator=document.createElement('section'); calculator.id='exchangeCalculator'; calculator.className='exchange-calculator'; calculator.innerHTML=`<div><span>ملخص الحاسبة</span><strong id="exchangeCalcLocal">0.00</strong><small id="exchangeCalcCurrency">اختر العملة والسعر</small></div><div><span>السعر المعتمد</span><strong id="exchangeCalcRate">0.00</strong><small id="exchangeCalcDifference">—</small></div><div><span>رصيد الصندوق</span><strong id="exchangeCashboxBalance">—</strong><small id="exchangeCashboxCurrency">بالعملة المختارة</small></div><div class="exchange-calculator-status" id="exchangeCalcStatus">جاهز لإدخال العملية</div><button class="secondary-btn mini-btn" type="button" onclick="syncSelectedExchangeRate()">اعتماد سعر الدليل</button>`; const actions=card.querySelector('.form-actions'); if (actions) actions.before(calculator); else card.append(calculator); ['foreignAmount','dealRate'].forEach((id) => document.getElementById(id)?.addEventListener('input',calculateExchange)); const currencyField=document.getElementById('exchangeCurrency'); currencyField?.addEventListener('change',()=>{ applyExchangeDefaultRate(); loadExchangeCashboxBalance(); }); document.getElementById('exchangeCashbox')?.addEventListener('change',loadExchangeCashboxBalance); applyExchangeDefaultRate(); loadExchangeCashboxBalance(); }
async function loadExchangeCashboxBalance() { const cashboxId=document.getElementById('exchangeCashbox')?.value; const currencyId=document.getElementById('exchangeCurrency')?.value; const target=document.getElementById('exchangeCashboxBalance'); const label=document.getElementById('exchangeCashboxCurrency'); if (!target || !cashboxId || !currencyId) return; const response=await window.sarafa.dataCall('quickEntryBalances',{cashboxId,accountId:document.getElementById('exchangeCounterAccount')?.value || 0,currencyId}); const currency=live.currencies.find((item) => String(item.id) === String(currencyId)); if (!response.ok) { target.textContent='غير متاح'; return; } target.textContent=fmt(response.data.cashboxBalance); if (label) label.textContent=currency ? `${currency.name_ar} (${currency.code})` : 'بالعملة المختارة'; }
function calculateExchange() {
  const amount=Number(document.getElementById('foreignAmount')?.value||0), rate=Number(document.getElementById('dealRate')?.value||0), fee=Number(document.getElementById('handling')?.value||0); const type=document.getElementById('exchangeType')?.value || 'sell'; const currency=live.currencies.find((item) => String(item.id) === String(document.getElementById('exchangeCurrency')?.value)); const defaultRate=rateForCurrency(currency?.id,type); const local=amount*rate+fee; const target=document.getElementById('localAmount'); if(target) target.value=local.toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2}); const localText=document.getElementById('exchangeCalcLocal'); const rateText=document.getElementById('exchangeCalcRate'); const currencyText=document.getElementById('exchangeCalcCurrency'); const difference=document.getElementById('exchangeCalcDifference'); const status=document.getElementById('exchangeCalcStatus'); if (localText) localText.textContent=fmt(local); if (rateText) rateText.textContent=fmt(rate); if (currencyText) currencyText.textContent=currency ? `${currency.name_ar} (${currency.code}) — المقابل المحلي شامل المناولة` : 'اختر العملة والسعر'; const delta=rate-defaultRate; if (difference) difference.textContent=currency && defaultRate ? `سعر الدليل ${fmt(defaultRate)} · فرق ${delta >= 0 ? '+' : ''}${fmt(delta)}` : 'لا يوجد سعر دليل بعد'; let warning=''; if (!amount || amount <= 0) warning='أدخل مبلغًا صحيحًا أكبر من صفر'; else if (!rate || rate <= 0) warning='أدخل سعر عملية صحيحًا'; else if (type === 'buy' && currency?.min_buy_rate != null && rate < Number(currency.min_buy_rate)) warning=`السعر أقل من الحد الأدنى المعتمد: ${fmt(currency.min_buy_rate)}`; else if (type === 'sell' && currency?.max_sell_rate != null && rate > Number(currency.max_sell_rate)) warning=`السعر أعلى من الحد الأقصى المعتمد: ${fmt(currency.max_sell_rate)}`; if (status) { status.textContent=warning || `المقابل المحلي ${fmt(local)}${fee ? ` · المناولة ${fmt(fee)}` : ''}`; status.classList.toggle('warning',Boolean(warning)); } }
