calculateExchange = function() { const amount=Number(document.getElementById('foreignAmount')?.value||0), rate=Number(document.getElementById('dealRate')?.value||0); const type=document.getElementById('exchangeType')?.value || 'sell'; const currency=live.currencies.find((item) => String(item.id) === String(document.getElementById('exchangeCurrency')?.value)); const defaultRate=rateForCurrency(currency?.id,type); const hasValues=amount > 0 && rate > 0; const local=hasValues ? amount*rate : null; const target=document.getElementById('localAmount'); if(target) target.value=local == null ? '' : local.toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2}); const localText=document.getElementById('exchangeCalcLocal'); const rateText=document.getElementById('exchangeCalcRate'); const currencyText=document.getElementById('exchangeCalcCurrency'); const difference=document.getElementById('exchangeCalcDifference'); const status=document.getElementById('exchangeCalcStatus'); if (localText) localText.textContent=local == null ? '—' : fmt(local); if (rateText) rateText.textContent=rate ? fmt(rate) : '—'; if (currencyText) currencyText.textContent=currency ? `${currency.name_ar} (${currency.code}) — المقابل المحلي` : 'اختر العملة والسعر'; const delta=rate-defaultRate; if (difference) difference.textContent=currency && defaultRate && rate ? `سعر الدليل ${fmt(defaultRate)} · فرق ${delta >= 0 ? '+' : ''}${fmt(delta)}` : 'لا يوجد سعر دليل بعد'; let warning=''; if (amount && amount <= 0) warning='أدخل مبلغًا صحيحًا أكبر من صفر'; else if (amount && !rate) warning='أدخل سعر صرف صحيحًا'; else if (type === 'buy' && currency?.min_buy_rate != null && rate && rate < Number(currency.min_buy_rate)) warning=`السعر أقل من الحد الأدنى المعتمد: ${fmt(currency.min_buy_rate)}`; else if (type === 'sell' && currency?.max_sell_rate != null && rate && rate > Number(currency.max_sell_rate)) warning=`السعر أعلى من الحد الأقصى المعتمد: ${fmt(currency.max_sell_rate)}`; if (status) { status.textContent=warning || (local == null ? 'أدخل المبلغ لإظهار المقابل المحلي' : `المقابل المحلي ${fmt(local)}`); status.classList.toggle('warning',Boolean(warning)); } };
function addVoucherNumberPreview() { const type = document.getElementById('voucherType'); if (!type || document.getElementById('voucherAutoNo')) return; const field = type.closest('.field'); field.insertAdjacentHTML('beforebegin', `<div class="field"><label>رقم السند التلقائي</label><input id="voucherAutoNo" value="${voucherPreview(type.value)}" readonly></div>`); type.addEventListener('change', () => { document.getElementById('voucherAutoNo').value = voucherPreview(type.value); }); }
function showReport(kind) {
  const titles = { daily: 'تقرير السندات', cashbox: 'حركة الصناديق', transfers: 'تقرير الحوالات', trial: 'دليل الحسابات', profits: 'أرباح بيع العملات' };
  let rows = [];
  if (kind === 'transfers') rows = live.transfers.map((item) => [item.transfer_no, item.transfer_type === 'outgoing' ? 'حوالة صادرة' : 'حوالة واردة', `${item.sender_name} → ${item.beneficiary_name}`, `${fmt(item.amount)} ${item.currency_code}`, item.status]);
  else if (kind === 'profits') rows = live.exchanges.map((item) => [item.operation_no, item.operation_type === 'buy' ? 'شراء عملة' : 'بيع عملة', item.currency_code, fmt(item.local_value), item.status]);
  else if (kind === 'trial') rows = live.accounts.map((item) => [item.code, item.name_ar, item.account_type, item.active ? 'نشط' : 'موقوف', '—']);
  else if (kind === 'cashbox') rows = live.cashboxes.map((item) => [item.name_ar, item.branch_name, item.user_name || 'غير محدد', item.account_id || '—', item.active ? 'نشط' : 'موقوف']);
  else rows = live.vouchers.map((item) => [item.voucher_no, item.voucher_type === 'receipt' ? 'سند قبض' : 'سند صرف', item.cashbox_name, `${fmt(item.amount)} ${item.currency_code}`, item.status]);
  view.innerHTML = `<div class="page-head"><div><h2>${titles[kind] || titles.daily}</h2><p>تقرير مباشر مبني على بيانات MySQL الحالية</p></div><div><button class="primary-btn" onclick="previewPrint()">معاينة وطباعة</button> <button class="secondary-btn" onclick="navigate('reports')">← العودة للتقارير</button></div></div><div class="card"><div class="report-summary"><strong>الفرع:</strong> ${settings.branch} <strong>العملة:</strong> ${settings.baseCurrency} <strong>السنة:</strong> ${settings.fiscalYear}</div><div class="table-wrap" style="margin-top:16px"><table class="data-table"><thead><tr><th>المرجع</th><th>النوع</th><th>البيان</th><th>القيمة</th><th>الحالة</th></tr></thead><tbody>${rows.length ? rows.map((row) => `<tr>${row.map((cell, index) => `<td>${index === 4 ? badge(cell) : escapeHtml(cell)}</td>`).join('')}</tr>`).join('') : '<tr><td colspan="5">لا توجد بيانات ضمن هذا التقرير حتى الآن.</td></tr>'}</tbody></table></div></div>`;
}
function exchangeTypeView(type) { const title = type === 'buy' ? 'شراء العملات' : 'بيع العملات'; const rows = live.exchanges.filter((item) => item.operation_type === type).map((item) => `<tr><td>${item.operation_no}</td><td>${String(item.operation_date).slice(0, 10)}</td><td>${escapeHtml(item.customer_name || '—')}</td><td>${item.currency_code}</td><td>${fmt(item.amount)}</td><td>${fmt(item.deal_rate)}</td><td>${fmt(item.local_value)}</td><td>${badge(item.status === 'posted' ? 'مرحل' : item.status)}</td></tr>`).join(''); return `<div class="page-head"><div><h2>${title}</h2><p>سجل مستقل لعمليات ${title} مع السعر الافتراضي للعملة</p></div><button class="primary-btn" onclick="navigate('new-exchange-${type}')">＋ ${title.slice(0, -1)} جديدة</button></div><div class="table-wrap"><table class="data-table"><thead><tr><th>رقم العملية</th><th>التاريخ</th><th>العميل</th><th>العملة</th><th>المبلغ</th><th>السعر</th><th>المقابل</th><th>الحالة</th></tr></thead><tbody>${rows || '<tr><td colspan="8">لا توجد عمليات بعد.</td></tr>'}</tbody></table></div>`; }
function transferTypeView(type) { const title = type === 'incoming' ? 'الحوالات الواردة' : 'الحوالات الصادرة'; const rows = live.transfers.filter((item) => item.transfer_type === type).map((item) => { const state = item.status === 'completed' ? 'مكتملة' : item.status === 'pending' ? 'قيد الانتظار' : 'ملغاة'; const actions = item.status === 'pending' ? `${type === 'incoming' ? `<button class="primary-btn mini-btn" onclick="navigate('transfer-payout')">صرف</button>` : ''} <button class="secondary-btn mini-btn" onclick="cancelTransfer(${item.id})">إلغاء</button>` : '—'; return `<tr><td>${item.transfer_no}</td><td>${escapeHtml(item.sender_name)}</td><td>${escapeHtml(item.beneficiary_name)}</td><td>${fmt(item.amount)} ${item.currency_code}</td><td>${fmt(item.commission)}</td><td>${badge(state)}</td><td>${actions}</td></tr>`; }).join(''); return `<div class="page-head"><div><h2>${title}</h2><p>سجل ونموذج مستقلان للحوالات ${type === 'incoming' ? 'الواردة وصرفها' : 'الصادرة'}</p></div><button class="primary-btn" onclick="navigate('new-transfer-${type}')">＋ حوالة ${type === 'incoming' ? 'واردة' : 'صادرة'} جديدة</button></div><div class="table-wrap"><table class="data-table"><thead><tr><th>الرقم</th><th>المرسل</th><th>المستفيد</th><th>المبلغ</th><th>العمولة</th><th>الحالة</th><th>إجراء</th></tr></thead><tbody>${rows || '<tr><td colspan="7">لا توجد حوالات ضمن هذا النوع.</td></tr>'}</tbody></table></div>`; }
function customersManagementView() {
  const body = live.customers.map((item) => `<tr><td>${escapeHtml(item.customer_no)}</td><td>${escapeHtml(item.full_name)}</td><td>${escapeHtml(item.phone || '—')}</td><td>${escapeHtml(item.linked_cashbox_name || 'غير مرتبط')}</td><td>${escapeHtml(item.linked_account_name || 'غير مرتبط')}</td><td>${escapeHtml({ customer: 'عميل', agent: 'وكيل', supplier: 'مورد' }[item.customer_type] || item.customer_type)}</td><td>${badge(item.is_blocked ? 'محظور' : item.active ? 'نشط' : 'موقوف')}</td><td><button class="secondary-btn mini-btn" onclick="openCustomerProfile(${item.id})">ملف العميل</button></td></tr>`).join('');
  return `<div class="page-head"><div><h2>العملاء والوكلاء</h2><p>من هذه النافذة تُفتح بيانات العميل ويُربط بالصندوق وحسابه في خطوة واحدة.</p></div><button class="primary-btn" onclick="navigate('customer-cashbox-link')">＋ فتح عميل وربطه بالصندوق</button></div><div class="toolbar"><input class="search" placeholder="ابحث بالاسم أو الرقم أو الهاتف..." oninput="filterRows(this)"><button class="secondary-btn" onclick="navigate('customers')">⟳ تحديث</button></div><div class="table-wrap"><table class="data-table"><thead><tr><th>الرقم</th><th>الاسم</th><th>الهاتف</th><th>الصندوق المرتبط</th><th>الحساب المرتبط</th><th>التصنيف</th><th>الحالة</th><th>إجراء</th></tr></thead><tbody>${body || '<tr><td colspan="8">لا توجد سجلات بعد.</td></tr>'}</tbody></table></div>`;
}
function customerManagementForm() {
  return `<div class="page-head"><div><h2>إضافة عميل أو وكيل</h2><p>تسجيل بيانات التواصل والهوية وسقف التعامل في MySQL</p></div><button class="secondary-btn" onclick="navigate('customers')">← العودة</button></div><div class="card"><div class="form-grid"><div class="field"><label>الاسم الكامل</label><input id="customerName" placeholder="الاسم الكامل"></div><div class="field"><label>رقم الهاتف</label><input id="customerPhone" placeholder="رقم الهاتف"></div><div class="field"><label>رقم الهوية / الوثيقة</label><input id="customerIdentity" placeholder="اختياري"></div><div class="field"><label>المنطقة / العنوان</label><input id="customerAddress" placeholder="المدينة أو العنوان"></div><div class="field"><label>التصنيف</label><select id="customerType"><option value="customer">عميل</option><option value="agent">وكيل</option><option value="supplier">مورد</option></select></div><div class="field"><label>سقف التعامل للعملية</label><input id="customerLimit" type="number" min="0" placeholder="فارغ = بلا سقف"></div><div class="field wide" style="grid-column:1/-1"><label>ملاحظات إدارية</label><textarea id="customerNotes" placeholder="تنبيهات أو بيانات مهمة عن العميل"></textarea></div></div><div class="form-actions"><button class="primary-btn" onclick="saveCustomer()">حفظ السجل</button><button class="secondary-btn" onclick="navigate('customers')">إلغاء</button></div></div>`;
}
function customerCashboxLinkForm() {
  const existing=selectOptions(live.customers.filter((item) => item.active), 'id', (item) => item.full_name);
  const cashboxes=selectOptions(live.cashboxes.filter((item) => item.active && item.account_id), 'id', (item) => item.name_ar);
  const parents=selectOptions(live.accounts.filter((item) => item.active), 'id', (item) => item.name_ar);
  return `<div class="page-head"><div><h2>فتح عميل وربطه بالصندوق</h2><p>نافذة واحدة: اختر عميلًا موجودًا أو أدخل عميلًا جديدًا، ثم اختر الصندوق واحفظ.</p></div><button class="secondary-btn" onclick="navigate('customers')">← العودة للعملاء</button></div><section class="customer-cashbox-link-card"><div class="link-step"><span>1</span><div><strong>العميل</strong><small>اختيار عميل موجود أو إدخال بيانات عميل جديد.</small></div></div><div class="form-grid"><div class="field"><label>عميل موجود</label><select id="linkCustomerExisting" onchange="toggleLinkCustomerFields()">${existing}</select></div><div class="field link-new-customer"><label>اسم العميل الجديد</label><input id="linkCustomerName"></div><div class="field link-new-customer"><label>الهاتف</label><input id="linkCustomerPhone"></div><div class="field link-new-customer"><label>العنوان</label><input id="linkCustomerAddress"></div><div class="field link-new-customer"><label>التصنيف</label><select id="linkCustomerType"><option value="customer">عميل</option><option value="agent">وكيل</option><option value="supplier">مورد</option></select></div></div><div class="link-step"><span>2</span><div><strong>الصندوق والحساب</strong><small>يربط النظام العميل بالصندوق وينشئ حسابه الفرعي تلقائيًا عند الحاجة.</small></div></div><div class="form-grid"><div class="field"><label>الصندوق</label><select id="linkCashbox">${cashboxes}</select></div><div class="field"><label>اسم الحساب المحاسبي</label><input id="linkAccountName" placeholder="يُنشأ تلقائيًا باسم العميل عند تركه فارغًا"></div><div class="field"><label>الحساب الأب</label><select id="linkParentAccount">${parents}</select></div><div class="field"><label>طبيعة الحساب</label><select id="linkAccountType"><option value="asset">مدين / أصول</option><option value="liability">دائن / خصوم</option></select></div><div class="field"><label>الحساب الختامي</label><select id="linkStatementCategory"><option value="balance_sheet">الميزانية العمومية</option><option value="profit_loss">الأرباح والخسائر</option></select></div><div class="field"><label>رتبة الحساب</label><input id="linkAccountRank" type="number" value="0" min="0"></div></div><div class="form-actions"><button class="primary-btn" onclick="saveCustomerCashboxLink()">فتح وربط وحفظ</button><button class="secondary-btn" onclick="navigate('customers')">إلغاء</button></div></section>`;
}
function customerProfileView() {
  const item = live.customers.find((customer) => Number(customer.id) === Number(editingCustomerId));
  if (!item) return customersManagementView();
  const exchanges = live.exchanges.filter((exchange) => Number(exchange.customer_id) === Number(item.id)).slice(0, 15);
  const transferMatches = live.transfers.filter((transfer) => String(transfer.sender_name) === String(item.full_name) || String(transfer.beneficiary_name) === String(item.full_name)).slice(0, 15);
  const exchangeRows = exchanges.map((exchange) => `<tr><td>${escapeHtml(exchange.operation_no)}</td><td>${formatArabicDate(String(exchange.operation_date).slice(0,10))}</td><td>${exchange.operation_type === 'buy' ? 'شراء' : 'بيع'}</td><td>${fmt(exchange.amount)} ${escapeHtml(exchange.currency_code)}</td><td>${fmt(exchange.local_value)}</td></tr>`).join('');
  const transferRows = transferMatches.map((transfer) => `<tr><td>${escapeHtml(transfer.transfer_no)}</td><td>${transfer.transfer_type === 'incoming' ? 'واردة' : 'صادرة'}</td><td>${fmt(transfer.amount)} ${escapeHtml(transfer.currency_code)}</td><td>${badge(transfer.status === 'pending' ? 'قيد الانتظار' : transfer.status === 'completed' ? 'مكتملة' : 'ملغاة')}</td></tr>`).join('');
  return `<div class="page-head"><div><h2>ملف العميل — ${escapeHtml(item.full_name)}</h2><p>تحديث البيانات والحظر ومراجعة التعاملات السريعة</p></div><button class="secondary-btn" onclick="navigate('customers')">← العودة للعملاء</button></div><div class="customer-profile-summary"><div><span>رقم العميل</span><strong>${escapeHtml(item.customer_no)}</strong></div><div><span>الهاتف</span><strong>${escapeHtml(item.phone || '—')}</strong></div><div><span>سقف التعامل</span><strong>${item.max_transaction_amount == null ? 'بلا سقف' : fmt(item.max_transaction_amount)}</strong></div><div><span>الحالة</span>${badge(item.is_blocked ? 'محظور' : item.active ? 'نشط' : 'موقوف')}</div></div><div class="card"><div class="form-grid"><div class="field"><label>الاسم الكامل</label><input id="profileCustomerName" value="${escapeHtml(item.full_name)}"></div><div class="field"><label>الهاتف</label><input id="profileCustomerPhone" value="${escapeHtml(item.phone || '')}"></div><div class="field"><label>رقم الهوية / الوثيقة</label><input id="profileCustomerIdentity" value="${escapeHtml(item.identity_no || '')}"></div><div class="field"><label>العنوان</label><input id="profileCustomerAddress" value="${escapeHtml(item.address_ar || '')}"></div><div class="field"><label>سقف التعامل</label><input id="profileCustomerLimit" type="number" value="${item.max_transaction_amount == null ? '' : Number(item.max_transaction_amount)}"></div><div class="field"><label><input id="profileCustomerBlocked" type="checkbox" ${item.is_blocked ? 'checked' : ''}> حظر التعامل مع العميل</label><input id="profileCustomerBlockReason" value="${escapeHtml(item.block_reason || '')}" placeholder="سبب الحظر عند التفعيل"></div><div class="field" style="grid-column:1/-1"><label>ملاحظات</label><textarea id="profileCustomerNotes">${escapeHtml(item.notes || '')}</textarea></div></div><div class="form-actions"><button class="primary-btn" onclick="saveCustomerProfile(${item.id})">حفظ ملف العميل</button><button class="secondary-btn" onclick="previewPrint()">طباعة الملف</button></div></div><div class="grid-2" style="margin-top:18px"><div class="table-wrap"><table class="data-table"><thead><tr><th colspan="5">آخر عمليات الصرافة</th></tr><tr><th>الرقم</th><th>التاريخ</th><th>النوع</th><th>العملة</th><th>المقابل المحلي</th></tr></thead><tbody>${exchangeRows || '<tr><td colspan="5">لا توجد عمليات صرافة مرتبطة.</td></tr>'}</tbody></table></div><div class="table-wrap"><table class="data-table"><thead><tr><th colspan="4">آخر الحوالات المطابقة للاسم</th></tr><tr><th>الرقم</th><th>النوع</th><th>المبلغ</th><th>الحالة</th></tr></thead><tbody>${transferRows || '<tr><td colspan="4">لا توجد حوالات مطابقة.</td></tr>'}</tbody></table></div></div>`;
}
function alertsView() { return `<div class="page-head"><div><h2>مركز التنبيهات والمتابعة</h2><p>تنبيهات تشغيلية من قاعدة البيانات وإعدادات النسخ الاحتياطي</p></div><button class="secondary-btn" onclick="loadAlerts()">⟳ تحديث التنبيهات</button></div><div id="alertsList" class="alert-list"><div class="card">جارٍ تحميل التنبيهات…</div></div>`; }
function auditLogView() { return `<div class="audit-log-screen"><div class="audit-log-heading"><div><h2>سجل التدقيق والمراجعة</h2><p>متابعة يومية واضحة للعمليات والتعديلات</p></div></div><section class="audit-log-metrics" aria-label="ملخص السجل"><article class="audit-log-metric metric-operations"><span class="audit-log-metric-icon" aria-hidden="true">✓</span><div><span>عمليات اليوم</span><strong id="auditTodayOperations">0 <small>عملية</small></strong></div></article><article class="audit-log-metric metric-updates"><span class="audit-log-metric-icon" aria-hidden="true">✎</span><div><span>تعديلات اليوم</span><strong id="auditTodayUpdates">0 <small>تعديلات</small></strong></div></article><article class="audit-log-metric metric-deletions"><span class="audit-log-metric-icon" aria-hidden="true">⌫</span><div><span>حالات الحذف</span><strong id="auditTodayDeletions">0 <small>عملية</small></strong></div></article></section><div class="audit-log-actions" role="toolbar" aria-label="إجراءات سجل التدقيق"><button class="audit-log-action archive-action" type="button" onclick="navigate('secret-archive')"><span aria-hidden="true">▱</span> فتح الأرشيف السري</button><button class="audit-log-action refresh-action" type="button" onclick="loadAuditTrail()"><span aria-hidden="true">⟳</span> تحديث السجل</button></div><section class="card audit-log-filters"><div class="audit-filter-main"><div class="field audit-filter-search"><label for="auditQuery">بحث</label><div class="audit-search-wrap"><input id="auditQuery" class="search" placeholder="ابحث بالمستخدم أو الإجراء أو رقم المستند" oninput="filterRows(this)" autocomplete="off"><span aria-hidden="true">⌕</span></div><div class="audit-legend" aria-label="دليل ألوان الإجراءات"><span><i class="legend-dot add"></i>إضافة</span><span><i class="legend-dot edit"></i>تعديل</span><span><i class="legend-dot delete"></i>حذف</span><span><i class="legend-dot approve"></i>اعتماد</span></div></div><div class="field audit-filter-date"><label for="auditDate">تاريخ اليوم</label><div class="audit-date-wrap"><input id="auditDate" type="date" value="${todayIso()}"><span aria-hidden="true">▣</span></div></div><div class="field audit-filter-limit"><label for="auditLimit">عرض</label><select id="auditLimit" class="filter" onchange="loadAuditTrail()"><option value="100">آخر 100 حركة</option><option value="200" selected>آخر 200 حركة</option><option value="500">آخر 500 حركة</option></select></div><button class="audit-apply" type="button" onclick="loadAuditTrail()">تطبيق البحث</button></div></section><div class="table-wrap audit-log-table"><table class="data-table audit-log-data-table"><thead><tr><th>الوقت</th><th>المستخدم</th><th>الإجراء</th><th>العملية</th><th>التفاصيل</th><th>الحالة</th></tr></thead><tbody id="auditRows"><tr><td colspan="6">جارٍ تحميل السجل…</td></tr></tbody></table></div><div class="audit-help-row"><aside class="audit-help-card"><span class="audit-help-icon" aria-hidden="true">◉</span><div><strong>كيف تستخدم السجل؟</strong><span><b>•</b> اعرض الحركة اليومية بسرعة</span><span><b>•</b> افتح الأرشيف السري للتفاصيل الكاملة</span></div></aside></div></div>`; }
function managementReportsView() { return `<div class="page-head"><div><h2>التقارير الإدارية المتقدمة</h2><p>الربح والعمولات والصناديق والعملاء وفروقات الجرد</p></div><button class="secondary-btn" onclick="loadManagementReports()">⟳ تحديث التقارير</button></div><div id="managementReportsBody"><div class="card">جارٍ تحميل مؤشرات التقارير…</div></div>`; }
function incomeExpenseReportView() { const start=`${todayIso().slice(0,8)}01`; return `<div class="report-single-title"><h2>تقرير الإيرادات والمصروفات</h2></div><div class="report-single-actions"><button class="primary-btn" onclick="loadIncomeExpenseReport()">عرض التقرير</button><button class="secondary-btn" onclick="exportIncomeExpenseReport()">تصدير Excel</button><button class="secondary-btn" onclick="previewPrint()">PDF / طباعة</button></div><section class="card"><div class="form-grid"><div class="field"><label>من تاريخ</label>${dateField('incomeExpenseFrom',start)}</div><div class="field"><label>إلى تاريخ</label>${dateField('incomeExpenseTo',todayIso())}</div></div></section><section id="incomeExpenseBody" class="report-body"><div class="card">اختر الفترة ثم اضغط «عرض التقرير».</div></section>`; }
