async function activateView(name) { document.querySelectorAll('.toolbar-btn[data-view]').forEach((button) => button.classList.toggle('active', button.dataset.view === name)); const assetTask=window.ensureSarafaAssetsForView?.(name); if(assetTask){ setHeader((name==='data-analysis'?'مركز تحليل البيانات':'جارٍ تجهيز الأداة')); view.innerHTML='<section class="module-launch-skeleton inline-wait" role="status" aria-live="polite" aria-label="يرجى الانتظار"><span class="module-launch-spinner" aria-hidden="true"></span><div class="module-launch-copy"><strong>يرجى الانتظار</strong><small>جارٍ تجهيز الأداة المطلوبة</small></div></section>'; try { await assetTask; } catch(error) { showToast(error?.message||'تعذر تجهيز الأداة','error'); return; } } render(name); }
async function navigate(name) {
  if (!isModuleWindow && name !== 'dashboard' && workspaceTabs.has(String(name))) {
    if (String(name) !== activeWorkspaceTab) { rememberActiveWorkspaceTab(); switchWorkspaceTab(String(name)); }
    return;
  }
  const coreView=isCoreDirectoryView(name);
  const needsCoreForView=requiresCoreDirectories(name);
  const needsCustomersForView=requiresCustomerDirectories(name);
  if (!liveDataReady) {
    const refreshed=await ensureLiveData();
    if (!refreshed && !coreView && !needsCoreForView) { showToast('تعذر تحميل بيانات هذه الصفحة. تحقق من اتصال MySQL ثم أعد المحاولة.','error'); return; }
    initialDataHydration=false;
  }
  if ((needsCoreForView && !coreDirectoriesReady) || (needsCustomersForView && needsCustomerDirectoryRecovery())) {
    const recovered=await refreshCoreDirectories(true);
    if (!recovered || (needsCustomersForView && needsCustomerDirectoryRecovery())) { showToast('تعذر تحميل دليل هذه الشاشة. تحقق من اتصال MySQL ثم أعد المحاولة.','error'); return; }
    showToast('تم عرض الأدلة من قراءة متوافقة دون تعديل بيانات MySQL.','success');
  }
  if (!isModuleWindow && activeWorkspaceTab) rememberActiveWorkspaceTab();
  await activateView(name);
  if (!isModuleWindow && name !== 'dashboard') registerWorkspaceTab(name);
}
