function arabicAmountText(value, currency) { const number = Math.floor(Math.abs(Number(value) || 0)); const ones = ['صفر','واحد','اثنان','ثلاثة','أربعة','خمسة','ستة','سبعة','ثمانية','تسعة','عشرة','أحد عشر','اثنا عشر','ثلاثة عشر','أربعة عشر','خمسة عشر','ستة عشر','سبعة عشر','ثمانية عشر','تسعة عشر']; const tens = ['','','عشرون','ثلاثون','أربعون','خمسون','ستون','سبعون','ثمانون','تسعون']; const underHundred = (n) => n < 20 ? ones[n] : `${ones[n % 10] && n % 10 ? `${ones[n % 10]} و` : ''}${tens[Math.floor(n / 10)]}`; const underThousand = (n) => n < 100 ? underHundred(n) : `${n >= 200 ? (Math.floor(n / 100) === 2 ? 'مائتان' : `${ones[Math.floor(n / 100)]} مائة`) : 'مائة'}${n % 100 ? ` و${underHundred(n % 100)}` : ''}`; if (number < 1000) return `${underThousand(number)} ${currency}`; if (number < 1000000) return `${underThousand(Math.floor(number / 1000))} ألف${number % 1000 ? ` و${underThousand(number % 1000)}` : ''} ${currency}`; return `${number.toLocaleString('ar-EG')} ${currency}`; }
