async function cancelVoucher(voucherId, type) { if (!window.confirm('سيُنشئ النظام قيدًا عكسيًا ويلغي السند دون حذف تاريخه. هل تريد المتابعة؟')) return; const result = await window.sarafa.dataCall('cancelVoucher', { voucherId, cancelDate: new Date().toISOString().slice(0,10), notes: 'إلغاء إداري موثق' }); if (!result.ok) { showToast(result.error); return; } await refreshLiveData(true); navigate(type === 'payment' ? 'voucher-payment' : 'voucher-receipt'); showToast('تم إلغاء السند وترحيل القيد العكسي'); }
function editCurrency(currencyId) { editingCurrencyId = Number(currencyId); navigate('edit-currency'); }
async function saveCurrencyRates(currencyId) { const item = live.currencies.find((currency) => Number(currency.id) === Number(currencyId)); if (!item) { showToast('تعذر العثور على العملة'); return; } const buyRate=document.getElementById(`rate-buy-${currencyId}`).value, sellRate=document.getElementById(`rate-sell-${currencyId}`).value; const result = await window.sarafa.dataCall('updateCurrency', { currencyId, nameAr: item.name_ar, buyRate, sellRate, transferRate:(Number(buyRate || 0)+Number(sellRate || 0))/2, minBuyRate: item.min_buy_rate ?? '', maxSellRate: item.max_sell_rate ?? '' }); if (!result.ok) { showToast(result.error); return; } await refreshLiveData(true); render('currency-settings'); showToast('تم حفظ أسعار العملة'); }
async function saveEditedCurrency() { const item = live.currencies.find((currency) => Number(currency.id) === Number(editingCurrencyId)); if (!item) return; const buyRate=document.getElementById('editCurrencyBuy').value, sellRate=document.getElementById('editCurrencySell').value; const result = await window.sarafa.dataCall('updateCurrency', { currencyId: item.id, nameAr: document.getElementById('editCurrencyName').value, buyRate, sellRate, transferRate:(Number(buyRate || 0)+Number(sellRate || 0))/2, minBuyRate: document.getElementById('editCurrencyMinBuy').value, maxSellRate: document.getElementById('editCurrencyMaxSell').value }); if (!result.ok) { showToast(result.error); return; } editingCurrencyId = null; await refreshLiveData(true); navigate('currency-settings'); showToast('تم تعديل بيانات العملة'); }
async function toggleCurrencyActive(currencyId, active) { if (!window.confirm(active ? 'تفعيل هذه العملة؟' : 'إيقاف هذه العملة عن العمليات؟')) return; const result = await window.sarafa.dataCall('setCurrencyActive', { currencyId, active }); if (!result.ok) { showToast(result.error); return; } await refreshLiveData(true); render('currency-settings'); showToast(active ? 'تم تفعيل العملة' : 'تم إيقاف العملة'); }
function exitReportsWindow() { return closeActiveWindow(); }
async function closeWorkWindow() { const result = await window.sarafa.closeCurrentWindow?.(); if (!result?.ok) return navigate('dashboard'); return result; }
async function exportExcelFile() { const result = await window.sarafa.exportExcel(); if (result.ok) showToast('تم تصدير بيانات النظام إلى Excel'); else if (result.error) showToast(result.error); }
async function exportIncomeExpenseReport() { const dateFrom=document.getElementById('incomeExpenseFrom')?.value || ''; const dateTo=document.getElementById('incomeExpenseTo')?.value || ''; if (!dateFrom || !dateTo) { presentOperationError('اختر فترة التقرير قبل التصدير'); return; } const result=await window.sarafa.exportIncomeExpenseReport({ dateFrom,dateTo }); if (result.ok) showToast(`تم تصدير تقرير الإيرادات والمصروفات إلى Excel (${result.rows || 0} حسابات)`,'success'); else if (result.error) presentOperationError(result.error); }
async function importExcelFile() { const result = await window.sarafa.importExcel(); if (result.ok) { await refreshLiveData(true); showToast(`تم استيراد ${result.imported} سجل من Excel`); } else if (result.error) showToast(result.error); }
async function connectGoogleDrive() { const result = await window.sarafa.connectGoogleDrive(); if (result.ok) showToast('تم ربط Google Drive بنجاح'); else if (result.error) showToast(result.error); }
async function backupGoogleDrive() { const result = await window.sarafa.backupGoogleDrive(); if (result.ok) { await window.sarafa.dataCall('recordBackupActivity', { mode: 'google' }); await refreshAlertCount(); showToast(`تم حفظ النسخة في Google Drive: ${result.name}`); } else if (result.error) showToast(result.error); }
async function refreshAutomaticBackupStatus() { if (!window.sarafa.automaticBackupStatus) return; const result=await window.sarafa.automaticBackupStatus(); const label=document.getElementById('automaticBackupStatus'); if (!label || !result.ok) return; const last=result.state?.lastLocalAt ? new Date(result.state.lastLocalAt).toLocaleString('ar-EG') : 'لا توجد نسخة تلقائية بعد'; const cloud=result.googleConnected ? 'Google Drive مرتبط' : 'اربط Google Drive أولًا'; label.textContent=`${result.settings.enabled ? `مفعّل يوميًا ${result.settings.time}` : 'غير مفعّل'} — ${cloud} — آخر نسخة: ${last}`; }
async function configureAutomaticBackup() { const result=await window.sarafa.configureAutomaticBackup({ time:document.getElementById('automaticBackupTime')?.value || '23:55' }); if (!result.ok) { showToast(result.error || 'تعذر تفعيل النسخ اليومي'); return; } settings.automaticBackup={ ...(settings.automaticBackup || {}), enabled:true, time:result.time, google:true, local:true }; showToast(`تم تفعيل النسخ اليومي عند ${result.time}`); await refreshAutomaticBackupStatus(); }
async function runAutomaticBackupNow() { const result=await window.sarafa.runAutomaticBackup(); if (!result.ok) { showToast(result.error || 'تعذر اختبار النسخة التلقائية'); return; } showToast(result.google?.ok ? 'تم اختبار النسخة المحلية وGoogle Drive بنجاح' : 'تم حفظ النسخة المحلية؛ تحقق من ربط Google Drive'); await refreshAutomaticBackupStatus(); }
async function googleBackupsView() { const result = await window.sarafa.listGoogleBackups(); if (!result.ok) { showToast(result.error); return; } const rows = result.files.map((item) => `<tr><td>${escapeHtml(item.name)}</td><td>${String(item.createdTime || '').replace('T', ' ').slice(0, 19)}</td><td>${item.size ? `${Math.round(Number(item.size) / 1024)} KB` : '—'}</td><td><button class="primary-btn mini-btn" onclick="restoreGoogleBackup('${item.id}')">استعادة هذه النسخة</button></td></tr>`).join(''); view.innerHTML = `<div class="window-command-line"><span>نسخ Google Drive</span><button class="secondary-btn mini-btn" onclick="navigate('backup-center')">العودة للنسخ</button></div><div class="table-wrap"><table class="data-table"><thead><tr><th>اسم النسخة</th><th>تاريخ الإنشاء</th><th>الحجم</th><th>الإجراء</th></tr></thead><tbody>${rows || '<tr><td colspan="4">لا توجد نسخ سحابية بعد.</td></tr>'}</tbody></table></div>`; applyWindowExitAction('backup-center'); }
async function restoreGoogleBackup(fileId) { const result = await window.sarafa.restoreGoogleDrive(fileId); if (result.ok) { showToast('تمت الاستعادة من Google Drive بنجاح'); await refreshLiveData(true); navigate('dashboard'); } else if (result.error) showToast(result.error); }
async function saveOperationDefaults() { const operationDefaults = { cashboxId: document.getElementById('defaultCashbox')?.value || '', currencyId: document.getElementById('defaultCurrency')?.value || '', accountId: document.getElementById('defaultAccount')?.value || '', preventPastPosting: document.getElementById('preventPastPosting')?.checked === true }; const result = await window.sarafa.dataCall('setDatePostingPolicy', { preventPastPosting: operationDefaults.preventPastPosting }); if (!result.ok) { showToast(result.error); return; } settings.operationDefaults = operationDefaults; await window.sarafa.saveSettings(settings); showToast('تم حفظ القيم المثبّتة وسياسة التاريخ'); }
async function testDatabase() { await saveSettings(); const result = await window.sarafa.dbStatus(); await refreshTopConnectionStatus(); showToast(result.connected ? `تم الاتصال بقاعدة ${result.config.database} بنجاح` : 'تعذر الاتصال بـ MySQL؛ تحقق من البيانات والخدمة'); }
