async function saveCustomerCashboxLink() { const payload={ customerId:document.getElementById('linkCustomerExisting')?.value || null, fullName:document.getElementById('linkCustomerName')?.value || '', phone:document.getElementById('linkCustomerPhone')?.value || '', addressAr:document.getElementById('linkCustomerAddress')?.value || '', customerType:document.getElementById('linkCustomerType')?.value || 'customer', cashboxId:document.getElementById('linkCashbox')?.value || null, accountName:document.getElementById('linkAccountName')?.value || '', parentAccountId:document.getElementById('linkParentAccount')?.value || null, accountType:document.getElementById('linkAccountType')?.value || 'asset', statementCategory:document.getElementById('linkStatementCategory')?.value || 'balance_sheet', displayRank:document.getElementById('linkAccountRank')?.value || 0 }; const response=await window.sarafa.dataCall('createCustomerCashboxLink',payload); if(!response.ok){showToast(response.error);return;} const refreshed=await refreshLiveData(true); if(!refreshed){showToast('تم الحفظ، لكن تعذر تحديث البيانات. اضغط تحديث بعد التحقق من الاتصال.');return;} showToast('تم فتح العميل وربطه بالصندوق والحساب من نافذة واحدة'); activateView('customers'); }
