function saveCurrency() { const buyRate=document.getElementById('currencyBuy').value, sellRate=document.getElementById('currencySell').value; saveRecord('createCurrency', { code: document.getElementById('currencyCode').value, nameAr: document.getElementById('currencyName').value, buyRate, sellRate, transferRate:(Number(buyRate || 0)+Number(sellRate || 0))/2, minBuyRate: document.getElementById('currencyMinBuy').value, maxSellRate: document.getElementById('currencyMaxSell').value }, 'currency-settings', 'تم حفظ العملة في MySQL'); }
function quickEntrySelectText(id) { const field = document.getElementById(id); return field?.options?.[field.selectedIndex]?.text || ''; }
function updateQuickEntryMode() { const operation = document.getElementById('quickOperation')?.value || 'receipt'; const transfer = operation.startsWith('transfer-'); const config = { receipt:{ title:'سند قبض سريع', description:'استلام مبلغ إلى الصندوق مع قيد متوازن', number:voucherPreview('receipt'), party:'استلمنا من (اختياري)', placeholder:'اسم الدافع عند الحاجة' }, payment:{ title:'سند صرف سريع', description:'صرف مبلغ من الصندوق مع قيد متوازن', number:voucherPreview('payment'), party:'يصرف إلى (اختياري)', placeholder:'اسم المستلم عند الحاجة' }, 'transfer-incoming':{ title:'حوالة واردة سريعة', description:'استلام حوالة إلى الصندوق وتسجيل بيانات المرسل والمستلم', number:'رقم الحوالة يصدر تلقائيًا' }, 'transfer-outgoing':{ title:'حوالة صادرة سريعة', description:'إرسال حوالة من الصندوق وتسجيل بيانات المرسل والمستلم', number:'رقم الحوالة يصدر تلقائيًا' } }[operation]; document.getElementById('quickEntryTitle').textContent = config.title; document.getElementById('quickEntryDescription').textContent = config.description; document.getElementById('quickEntryNumber').textContent = config.number; document.querySelectorAll('.quick-transfer-field').forEach((field) => { field.hidden = !transfer; }); document.querySelector('.quick-party-field').hidden = transfer; if (!transfer) { document.getElementById('quickPartyLabel').textContent = config.party; document.getElementById('quickParty').placeholder = config.placeholder; } }
async function loadQuickEntryBalances() { const cashbox = document.getElementById('quickCashbox')?.value; const account = document.getElementById('quickAccount')?.value; const currency = document.getElementById('quickCurrency')?.value; if (!cashbox || !account || !currency) return; const response = await window.sarafa.dataCall('quickEntryBalances', { cashboxId: cashbox, accountId: account, currencyId: currency }); if (!response.ok) { document.getElementById('quickCashboxBalance').textContent = 'غير متاح'; document.getElementById('quickAccountBalance').textContent = 'غير متاح'; return; } const currencyText = quickEntrySelectText('quickCurrency').match(/\(([^)]+)\)/)?.[1] || ''; document.getElementById('quickCashboxBalance').textContent = `${fmt(response.data.cashboxBalance)} ${currencyText}`; document.getElementById('quickAccountBalance').textContent = `${fmt(response.data.accountBalance)} ${currencyText}`; }
function setupQuickEntry() { const root = view.querySelector('.quick-entry-card'); document.getElementById('quickOperation')?.addEventListener('change', updateQuickEntryMode); ['quickCashbox','quickAccount','quickCurrency'].forEach((id) => document.getElementById(id)?.addEventListener('change', loadQuickEntryBalances)); root?.addEventListener('keydown', (event) => { if (event.key === 'F9') { event.preventDefault(); saveQuickEntry(false); return; } if (event.key === 'F2') { event.preventDefault(); resetQuickEntry(); return; } if (event.key === 'Enter' && event.target.tagName !== 'TEXTAREA') { const fields = [...root.querySelectorAll('input:not([type="hidden"]), select, textarea')].filter((field) => !field.disabled && !field.closest('[hidden]')); const at = fields.indexOf(event.target); if (at >= 0 && fields[at + 1]) { event.preventDefault(); fields[at + 1].focus(); } } }); updateQuickEntryMode(); loadQuickEntryBalances(); }
function resetQuickEntry() { quickPrintVoucher = null; quickPrintTransfer = null; render('quick-entry'); }
async function saveQuickEntry(printAfter) { const operation = document.getElementById('quickOperation')?.value || 'receipt'; const common = { cashboxId: document.getElementById('quickCashbox')?.value, counterAccountId: document.getElementById('quickAccount')?.value, currencyId: document.getElementById('quickCurrency')?.value, amount: document.getElementById('quickAmount')?.value, notes: document.getElementById('quickNotes')?.value, referenceNo: document.getElementById('quickReference')?.value, voucherDate: document.getElementById('quickDate')?.value }; const isTransfer = operation.startsWith('transfer-'); const request = isTransfer ? { operation:'createTransfer', payload:{ transferType: operation === 'transfer-incoming' ? 'incoming' : 'outgoing', transferDate: common.voucherDate, currencyId: common.currencyId, amount: common.amount, senderName: document.getElementById('quickSender')?.value, beneficiaryName: document.getElementById('quickBeneficiary')?.value, agentId: document.getElementById('quickAgent')?.value || null, cashboxId: common.cashboxId, counterAccountId: common.counterAccountId, commission: document.getElementById('quickCommission')?.value || 0, notes: common.notes } } : { operation:'createVoucher', payload:{ voucherType: operation, ...common, partyName: document.getElementById('quickParty')?.value } }; const response = await window.sarafa.dataCall(request.operation, request.payload); if (!response.ok) { showToast(response.error); return; } if (printAfter) { if (isTransfer) quickPrintTransfer = { transferNo:response.data.transferNo,date:common.voucherDate,sender:document.getElementById('quickSender')?.value || '',beneficiary:document.getElementById('quickBeneficiary')?.value || '',agent:quickEntrySelectText('quickAgent'),notes:common.notes || '',reference:common.referenceNo || '',currency:quickEntrySelectText('quickCurrency'),cashbox:quickEntrySelectText('quickCashbox'),amount:Number(common.amount || 0),commission:Number(document.getElementById('quickCommission')?.value || 0),type:operation === 'transfer-incoming' ? 'incoming' : 'outgoing' }; else quickPrintVoucher = { voucherNo:response.data.voucherNo,date:common.voucherDate,party:document.getElementById('quickParty')?.value || '',handler:document.getElementById('quickHandler')?.value || '',notes:common.notes || '',reference:common.referenceNo || '',currency:quickEntrySelectText('quickCurrency'),cashbox:quickEntrySelectText('quickCashbox'),amount:Number(common.amount || 0),type:operation }; previewPrint(); quickPrintVoucher = null; quickPrintTransfer = null; } const refreshed = await refreshLiveData(true); if (!refreshed) { showToast('حُفظت العملية، لكن تعذر تحديث السجل. اضغط تحديث بعد التحقق من الاتصال.'); return; } dailyViewDate = operationIsoDate(isTransfer ? request.payload.transferDate : common.voucherDate) || todayIso(); showToast(isTransfer ? `تم حفظ الحوالة ${response.data.transferNo} وترحيل قيدها` : `تم حفظ السند ${response.data.voucherNo} وترحيل قيده`); activateView(isTransfer ? (operation === 'transfer-incoming' ? 'transfers-incoming' : 'transfers-outgoing') : (operation === 'receipt' ? 'voucher-receipt' : 'voucher-payment')); }
async function saveTransfer(printAfter=false) { const transferType=document.getElementById('transferType').value; const payload={ transferType,transferDate:document.getElementById('transferDate')?.value || todayIso(),currencyId:document.getElementById('transferCurrency').value,amount:document.getElementById('transferAmount').value,senderName:document.getElementById('senderName').value,senderPhone:document.getElementById('senderPhone').value,beneficiaryName:document.getElementById('beneficiaryName').value,beneficiaryPhone:document.getElementById('beneficiaryPhone').value,agentId:document.getElementById('transferAgent').value || null,cashboxId:document.getElementById('transferCashbox').value,counterAccountId:document.getElementById('transferCounterAccount').value,commission:document.getElementById('transferCommission')?.value || 0,notes:document.getElementById('transferNotes').value }; const printable={ transferNo:'',date:payload.transferDate,sender:payload.senderName,senderPhone:payload.senderPhone,beneficiary:payload.beneficiaryName,beneficiaryPhone:payload.beneficiaryPhone,agent:printSelectText('transferAgent'),notes:payload.notes,currency:printSelectText('transferCurrency'),cashbox:printSelectText('transferCashbox'),amount:Number(payload.amount || 0),commission:Number(payload.commission || 0),type:transferType }; const response=await window.sarafa.dataCall('createTransfer',payload); if(!response.ok){presentOperationError(response.error);return;} printable.transferNo=response.data.transferNo; const refreshed=await refreshLiveData(true); if(!refreshed){showToast('حُفظت الحوالة، لكن تعذر تحديث السجل. اضغط تحديث بعد التحقق من الاتصال.');return;} dailyViewDate=operationIsoDate(payload.transferDate) || todayIso(); showToast(`تم حفظ الحوالة ${response.data.transferNo} وترحيل قيدها المتوازن`); activateView(transferType === 'incoming' ? 'transfers-incoming' : 'transfers-outgoing'); if(printAfter){quickPrintTransfer=printable; previewPrint(); quickPrintTransfer=null;} }
function saveTransferPayout() { saveRecord('payoutTransfer', { transferId: document.getElementById('payoutTransfer').value, cashboxId: document.getElementById('payoutCashbox').value, payoutDate: document.getElementById('payoutDate').value, receiverName: document.getElementById('payoutReceiver').value, receiverIdNo: document.getElementById('payoutReceiverId').value, notes: document.getElementById('payoutNotes').value }, 'transfers', 'تم صرف الحوالة وترحيل سند الصرف'); }
function cancelTransfer(transferId) { if (window.confirm('سيُنشئ النظام قيدًا عكسيًا لإلغاء الحوالة. هل تريد المتابعة؟')) saveRecord('cancelTransfer', { transferId, cancelDate: new Date().toISOString().slice(0, 10), notes: 'إلغاء إداري موثق' }, 'transfers', 'تم إلغاء الحوالة وترحيل القيد العكسي'); }
function saveVoucher() { const voucherType = document.getElementById('voucherType').value; voucherDraft = null; saveRecord('createVoucher', { voucherType, cashboxId: document.getElementById('voucherCashbox').value, counterAccountId: document.getElementById('voucherCounterAccount').value, currencyId: document.getElementById('voucherCurrency').value, amount: document.getElementById('voucherAmount').value, partyName: document.getElementById('voucherParty').value, voucherDate: document.getElementById('voucherDate').value, referenceNo: document.getElementById('voucherReference').value, notes: document.getElementById('voucherNotes').value }, voucherType === 'payment' ? 'voucher-payment' : 'voucher-receipt', 'تم حفظ وترحيل السند والقيد المتوازن'); }
function saveExchange() { const operationType = document.getElementById('exchangeType')?.value || 'sell'; const amount=Number(document.getElementById('foreignAmount')?.value || 0); const rate=Number(document.getElementById('dealRate')?.value || 0); const currency=live.currencies.find((item) => String(item.id) === String(document.getElementById('exchangeCurrency')?.value)); if (!amount || !rate) { showToast('تحقق من المبلغ وسعر الصرف قبل الحفظ'); return; } if (operationType === 'buy' && currency?.min_buy_rate != null && rate < Number(currency.min_buy_rate)) { showToast(`السعر أقل من الحد الأدنى المعتمد: ${fmt(currency.min_buy_rate)}`); return; } if (operationType === 'sell' && currency?.max_sell_rate != null && rate > Number(currency.max_sell_rate)) { showToast(`السعر أعلى من الحد الأقصى المعتمد: ${fmt(currency.max_sell_rate)}`); return; } saveRecord('createExchange', { operationType, currencyId: document.getElementById('exchangeCurrency').value, cashboxId: document.getElementById('exchangeCashbox').value, counterAccountId: document.getElementById('exchangeCounterAccount').value, customerId: document.getElementById('exchangeCustomer').value || null, operationDate: document.getElementById('exchangeDate').value, amount, transferRate:rate, dealRate:rate, handlingFee:0, notes: document.getElementById('exchangeNotes')?.value || '' }, operationType === 'buy' ? 'exchange-buy' : 'exchange-sell', 'تم حفظ وترحيل عملية الصرافة والقيد'); }
