function auditFriendlyKey(key) { const raw=String(key || ''); return auditDetailKeyLabels[raw] || (/^[\u0600-\u06ff\s\d]+$/.test(raw) ? raw : raw.replace(/([a-z])([A-Z])/g,'$1 $2').replace(/[_-]+/g,' ')); }
function auditFriendlyValue(value, key = '', depth = 0) { if (value == null || value === '') return '—'; if (/password|pass|hash|token|secret|salt|recovery.?code/i.test(String(key))) return 'قيمة محمية'; if (typeof value === 'boolean') return value ? 'تشغيل' : 'إيقاف'; if (typeof value === 'number') return fmt(value); if (Array.isArray(value)) return value.length ? value.slice(0,6).map((item) => auditFriendlyValue(item,'',depth+1)).join('، ') : '—'; if (typeof value === 'object') return auditFriendlyEntries(value,depth+1) || '—'; const text=String(value).trim(); return auditValueLabels[text] || text; }
function auditFriendlyEntries(object, depth = 0) { if (!object || typeof object !== 'object' || depth > 3) return ''; return Object.entries(object).filter(([key]) => !/password|pass|hash|token|secret|salt|recovery.?code/i.test(key) || object[key] != null).slice(0,10).map(([key,value]) => `${auditFriendlyKey(key)}: ${auditFriendlyValue(value,key,depth)}`).join(' · '); }
function auditFriendlyDetails(value, emptyText = 'لا توجد تفاصيل إضافية') { if (value == null || value === '' || value === '{}' || value === 'null') return emptyText; let parsed=value; if (typeof value === 'string') { try { parsed=JSON.parse(value); } catch { return String(value).replace(/[{}["]+/g,' ').replace(/\s+/g,' ').trim() || emptyText; } } return typeof parsed === 'object' ? (auditFriendlyEntries(parsed) || emptyText) : auditFriendlyValue(parsed); }
function auditActionLabel(value) { const raw=String(value || '').trim(); return auditActionLabels[raw] || (/^[\u0600-\u06ff\s\d]+$/.test(raw) ? raw : `إجراء: ${raw.replace(/[_-]+/g,' ')}`); }
function auditEntityLabel(value, id) { const raw=String(value || '').trim(); const label=auditEntityLabels[raw] || (/^[\u0600-\u06ff\s\d]+$/.test(raw) ? raw : `سجل ${raw.replace(/[_-]+/g,' ')}`); const numericId=String(id ?? '').trim(); return /^\d+$/.test(numericId) ? `${label} رقم ${numericId}` : label; }
