function enterEligibleFields(root) { return [...root.querySelectorAll('.field input,.field select,.field textarea')].filter((field) => !field.disabled && !field.readOnly && !field.closest('[hidden]')); }
function handleEnterWithin(root, event, onComplete) {
  if (event.key !== 'Enter' || event.isComposing || event.target?.tagName === 'TEXTAREA') return;
  const fields = enterEligibleFields(root); const at = fields.indexOf(event.target);
  if (at < 0) return;
  event.preventDefault();
  if (!event.target.checkValidity()) { event.target.reportValidity(); return; }
  if (fields[at + 1]) { fields[at + 1].focus(); return; }
  const invalid = fields.find((field) => !field.checkValidity());
  if (invalid) { invalid.reportValidity(); invalid.focus(); return; }
  onComplete();
}
