function voucherPrintData() { if (quickPrintVoucher) return { ...quickPrintVoucher, reference:'', handler:quickPrintVoucher.handler || '' }; const selectText = (id) => { const field = document.getElementById(id); return field?.options?.[field.selectedIndex]?.text || ''; }; const field = (id) => document.getElementById(id)?.value?.trim() || ''; const quickMode = currentView === 'quick-entry'; const amount = Number(field(quickMode ? 'quickAmount' : 'voucherAmount')) || 0; const quickType = field('quickOperation'); const type = quickMode && ['receipt', 'payment'].includes(quickType) ? quickType : document.getElementById('voucherType')?.value || ''; return { voucherNo: quickMode ? document.getElementById('quickEntryNumber')?.textContent?.trim() || '' : field('voucherAutoNo'), date:field(quickMode ? 'quickDate' : 'voucherDate'), party:quickMode ? '' : field('voucherParty'), handler:field(quickMode ? 'quickHandler' : 'voucherHandler'), notes:field(quickMode ? 'quickNotes' : 'voucherNotes'), reference:'', currency:selectText(quickMode ? 'quickCurrency' : 'voucherCurrency'), cashbox:selectText(quickMode ? 'quickCashbox' : 'voucherCashbox'), amount, type }; }
