function quickEntryRecordsMarkup() { return `<section id="quickRecordsPanel" class="quick-records-panel"><div class="quick-records-head"><strong id="quickRecordsTitle">سجل سند القبض</strong><span id="quickRecordsDate">${formatArabicDate(todayIso())}</span></div><div class="quick-records-table-wrap"><table><thead><tr><th>رقم العملية</th><th>الطرف / البيان</th><th>العملة</th><th>المبلغ</th><th>الملاحظة</th><th>وقت التنفيذ</th><th>الحالة</th></tr></thead><tbody id="quickRecordsRows"></tbody></table></div></section>`; }
function renderQuickEntryRecords() { const operation = document.getElementById('quickOperation')?.value || 'receipt'; const date = document.getElementById('quickDate')?.value || todayIso(); const panel = document.getElementById('quickRecordsPanel'); if (!panel) return; const titles = { receipt:'سجل سندات القبض', payment:'سجل سندات الصرف', 'transfer-incoming':'سجل الحوالات الواردة', 'transfer-outgoing':'سجل الحوالات الصادرة', 'buy-currency':'سجل شراء العملات', 'sell-currency':'سجل بيع العملات' }; panel.dataset.quickOperation = operation; document.getElementById('quickRecordsTitle').textContent = titles[operation] || 'سجل العمليات'; document.getElementById('quickRecordsDate').textContent = formatArabicDate(date); const rows = quickEntryRecordRows(operation, date); document.getElementById('quickRecordsRows').innerHTML = rows || '<tr><td colspan="6">لا توجد عمليات لهذا النوع في التاريخ المختار.</td></tr>'; }
