  if (!root) return;
  root.classList.add('quick-entry-structure-locked');
  const sections={
    '.quick-value-grid':['quickCurrency','quickAmount','quickDealRate','quickLocalAmount'],
    '.quick-source-grid':['quickCashbox','quickAccount'],
    '.quick-details-grid':['quickTransferNumber','quickSender','quickBeneficiary','quickAgent','quickCommission','quickNotes','quickHandler']
  };
  Object.entries(sections).forEach(([selector,ids])=>{
    const section=root.querySelector(selector);
    if (!section) return;
    ids.forEach((id)=>{
      const field=document.getElementById(id)?.closest('.field');
      if (field && field.parentElement !== section) section.append(field);
    });
    section.style.removeProperty('grid-template-columns');
    section.style.removeProperty('text-align');
  });
