  document.getElementById('quickCurrency')?.addEventListener('change', () => { syncQuickExchangeRate(); loadQuickEntryBalances(); });
  document.getElementById('quickDate')?.addEventListener('change', renderQuickEntryRecords);
  ['quickCashbox','quickAccount'].forEach((id) => document.getElementById(id)?.addEventListener('change', loadQuickEntryBalances));
